var e={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`},UFMT:{nome:`UFMT`,cor:`#7C3AED`},UFBA:{nome:`UFBA`,cor:`#DC2626`},UFPE:{nome:`UFPE`,cor:`#059669`}},t={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pós:{nome:`Pós-Graduação`,cor:`#D97706`}},n={celular:{nome:`Fisiologia Celular`,eixo:`pre`},nervoso:{nome:`Sistema Nervoso`,eixo:`pre`},muscular:{nome:`Fisiologia Muscular`,eixo:`pre`},cardiovascular:{nome:`Sistema Cardiovascular`,eixo:`clin`},respiratorio:{nome:`Sistema Respiratório`,eixo:`clin`},renal:{nome:`Sistema Renal`,eixo:`clin`},digestorio:{nome:`Sistema Digestório`,eixo:`clin`},endocrino:{nome:`Sistema Endócrino`,eixo:`pre`},reprodutivo:{nome:`Sistema Reprodutivo`,eixo:`prod`},imunológico:{nome:`Sistema Imunológico`,eixo:`pre`},hematologia:{nome:`Fisiologia do Sangue`,eixo:`pre`},termorregulação:{nome:`Termorregulação`,eixo:`pre`},metabolismo:{nome:`Metabolismo`,eixo:`pre`},nutrição:{nome:`Fisiologia da Nutrição`,eixo:`prod`},lactação:{nome:`Fisiologia da Lactação`,eixo:`prod`},exercício:{nome:`Fisiologia do Exercício`,eixo:`pre`}},r=[{id:`fisio-001`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso Médico Veterinário 2023`,tipo:`concurso`,topico:`celular`,subtopico:`Transporte de membrana`,dificuldade:`medio`,enunciado:`A respeito do transporte através da membrana celular, assinale a alternativa correta:`,alternativas:[`O transporte ativo primário utiliza diretamente a energia do ATP para mover substâncias contra seu gradiente de concentração.`,`O transporte passivo facilitado requer energia metabólica para o deslocamento de moléculas de alto peso molecular.`,`A osmose é o transporte de solutos do meio de maior para o de menor concentração, através da membrana semipermeável.`,`A difusão simples ocorre apenas para moléculas polares de pequeno porte, como a glicose e aminoácidos.`,`O transporte vesicular é exclusivo de células procariotas e não ocorre em células eucariotas animais.`],resposta_correta:`A`,explicacao:`O transporte ativo primário, como a bomba Na⁺/K⁺-ATPase, utiliza diretamente a energia da hidrólise do ATP para mover íons contra seu gradiente eletroquímico. O transporte passivo facilitado (opção B) NÃO requer energia. A osmose (opção C) é o transporte de ÁGUA, não de solutos. A difusão simples (opção D) ocorre para moléculas apolares (O₂, CO₂), não polares. O transporte vesicular (opção E) ocorre em eucariotas por endocitose/exocitose.`},{id:`fisio-002`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`celular`,subtopico:`Potencial de ação`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir, considerando os mecanismos de despolarização e repolarização da membrana celular.`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`Durante a fase de platô do potencial de ação cardíaco, os canais de cálcio do tipo L permanecem abertos, contrabalançando a saída de potássio e mantendo o potencial de membrana próximo de 0 mV por um período prolongado.`,explicacao:`Nos cardiomiócitos ventriculares, o potencial de ação possui uma fase de platô (fase 2) caracterizada pelo influxo de Ca²⁺ através dos canais de Ca²⁺ tipo L, que se contrabalança com a saída lenta de K⁺. Isso prolonga a duração do potencial de ação (~200-300 ms), sendo essencial para a contração sustentada do miocárdio e permitindo o enchimento ventricular adequado.`},{id:`fisio-003`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`celular`,subtopico:`Canais iônicos`,dificuldade:`medio`,enunciado:`Os canais iônicos presentes na membrana celular podem ser classificados quanto ao mecanismo de abertura. Assinale a alternativa que apresenta corretamente um tipo de canal e seu mecanismo:`,alternativas:[`Canais mecânicos — abrem em resposta a alterações na voltagem da membrana.`,`Canais ligante-dependentes — abrem quando um neurotransmissor ou outro ligante se liga ao canal.`,`Canais de leakage — abrem exclusivamente na presença de ATP citoplasmático.`,`Canais voltagem-dependentes — abrem pela ligação de hormônios peptídicos em seus receptores.`,`Canais de aquaporinas — são canais de Na⁺ que facilitam a difusão de sódio.`],resposta_correta:`B`,explicacao:`Os canais ligante-dependentes (ou quimicamente dependentes) abrem quando uma molécula específica (neurotransmissor, hormônio) se liga a um sítio receptor no canal. Canais mecânicos (opção A) respondem a estímulos mecânicos/deformação. Canais de leakage (opção C) permanecem continuamente abertos. Canais voltagem-dependentes (opção D) respondem a alterações no potencial de membrana. Aquaporinas (opção E) são canais específicos para água.`},{id:`fisio-004`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Médico Veterinário Prefeitura SP 2020`,tipo:`concurso`,topico:`celular`,subtopico:`Potencial de membrana`,dificuldade:`facil`,enunciado:`O potencial de repouso da membrana celular, em neurônios mamíferos, é aproximadamente:`,alternativas:[`+30 mV`,`0 mV`,`-70 mV`,`-120 mV`,`+70 mV`],resposta_correta:`C`,explicacao:`O potencial de repouso da membrana em neurônios mamíferos é de aproximadamente -70 mV (variando de -60 a -80 mV conforme o tipo celular). Este valor negativo é mantido principalmente pela bomba Na⁺/K⁺-ATPase (que exporta 3 Na⁺ e importa 2 K⁺) e pela permeabilidade diferencial da membrana ao K⁺ (maior) em relação ao Na⁺ (menor).`},{id:`fisio-005`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`concurso`,topico:`celular`,subtopico:`Bomba Na/K`,dificuldade:`medio`,enunciado:`A bomba Na⁺/K⁺-ATPase é uma proteína de membrana fundamental para a homeostase celular. Sobre seu funcionamento, é CORRETO afirmar:`,alternativas:[`A cada ciclo, transporta 3 íons Na⁺ para o meio intracelular e 2 íons K⁺ para o meio extracelular.`,`É uma proteína canal que permite a difusão passiva de Na⁺ e K⁺ através da membrana.`,`A cada ciclo, transporta 2 íons Na⁺ para o meio extracelular e 3 íons K⁺ para o meio intracelular.`,`A cada ciclo, transporta 3 íons Na⁺ para o meio extracelular e 2 íons K⁺ para o meio intracelular, consumindo 1 ATP.`,`Funciona apenas durante a despolarização da membrana e é inibida durante o potencial de repouso.`],resposta_correta:`D`,explicacao:`A bomba Na⁺/K⁺-ATPase é uma ATPase tipo P que, a cada ciclo de funcionamento, transporta ativamente 3 íons Na⁺ para o meio extracelular e 2 íons K⁺ para o meio intracelular, consumindo 1 molécula de ATP. Isso mantém as concentrações iônicas: [Na⁺] alta fora e [K⁺] alta dentro da célula. A bomba funciona continuamente, não apenas durante a despolarização.`},{id:`fisio-006`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA Área Animal 2023`,tipo:`concurso`,topico:`nervoso`,subtopico:`Sinapse química`,dificuldade:`dificil`,enunciado:`A respeito da transmissão sináptica no sistema nervoso, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A acetilcolinesterase presente na fenda sináptica hidrolisa a acetilcolina em colina e acetato, sendo este mecanismo essencial para a terminação do sinal colinérgico e a prevenção da despolarização tônica contínua da membrana pós-sináptica.`,explicacao:`A acetilcolinesterase (AChE) é a enzima responsável pela degradação rápida da acetilcolina (ACh) na fenda sináptica, hidrolisando-a em colina e ácido acético (acetato). Esse processo é fundamental para encerrar a transmissão do impulso nervoso nas sinapses colinérgicas. A inibição da AChE (por organofosforados, por exemplo) causa acúmulo de ACh e despolarização tônica contínua, levando a fasciculações musculares, broncoespasmo e morte.`},{id:`fisio-007`,banca:`FCC`,ano:2022,prova:`FCC — Professor de Fisiologia Veterinária UNESP 2022`,tipo:`concurso`,topico:`nervoso`,subtopico:`Neurotransmissores`,dificuldade:`medio`,enunciado:`Sobre os neurotransmissores e seus respectivos receptores, assinale a alternativa CORRETA:`,alternativas:[`O GABA é o principal neurotransmissor excitatório do sistema nervoso central de mamíferos.`,`Os receptores nicotínicos de acetilcolina são do tipo metabotrópico e acionam segundos mensageiros.`,`A noradrenalina é o principal neurotransmissor das fibras pós-ganglionares do sistema nervoso simpático.`,`A serotonina é exclusiva do sistema nervoso entérico e não atua no encéfalo.`,`Os receptores NMDA são canais de cloreto ativados por GABA.`],resposta_correta:`C`,explicacao:`A noradrenalina (norepinefrina) é o principal neurotransmissor das fibras pós-ganglionares simpáticas (exceto nas glândulas sudoríparas e alguns vasos, que usam ACh). O GABA (opção A) é o principal neurotransmissor INIBITÓRIO. Os receptores nicotínicos (opção B) são ionotrópicos (canais iônicos), não metabotrópicos. A serotonina (opção D) atua amplamente no SNC (humor, sono, apetite). Os receptores NMDA (opção E) são canais de Ca²⁺/Na⁺ ativados por glutamato.`},{id:`fisio-008`,banca:`UFMG`,ano:2021,prova:`UFMG — Residência em Clínica de Pequenos Animais 2021`,tipo:`residencia`,topico:`nervoso`,subtopico:`Reflexos`,dificuldade:`medio`,enunciado:`O arco reflexo simples é composto por cinco elementos. Assinale a alternativa que apresenta a sequência CORRETA dos componentes, na ordem em que o estímulo é processado:`,alternativas:[`Eferente → Centro integrador → Receptor → Efetor → Aferente`,`Receptor → Aferente → Centro integrador → Eferente → Efetor`,`Centro integrador → Receptor → Aferente → Efetor → Eferente`,`Efetor → Eferente → Centro integrador → Aferente → Receptor`,`Aferente → Receptor → Eferente → Centro integrador → Efetor`],resposta_correta:`B`,explicacao:`O arco reflexo simples segue a sequência: (1) Receptor (detecta o estímulo) → (2) Via aferente (neurônio sensorial conduz o impulso até a medula) → (3) Centro integrador (medula espinhal processa a informação) → (4) Via eferente (neurônio motor conduz a resposta) → (5) Efetor (músculo ou glândula executa a resposta). Exemplo: reflexo patelar — estiramento do tendão (receptor) → nervo femoral (aferente) → medula L3-L4 (centro) → nervo femoral (eferente) → quadríceps (efetor).`},{id:`fisio-009`,banca:`AVAMEC`,ano:2020,prova:`AVAMEC — Prova de Título em Clínica de Grandes Animais 2020`,tipo:`concurso`,topico:`nervoso`,subtopico:`Sistema nervoso autônomo`,dificuldade:`dificil`,enunciado:`Sobre o sistema nervoso autônomo (SNA) de animais domésticos, é CORRETO afirmar:`,alternativas:[`A divisão parassimpática utiliza acetilcolina como neurotransmissor tanto nas sinapses pré quanto pós-ganglionares.`,`A divisão simpática utiliza noradrenalina como neurotransmissor nas sinapses pré-ganglionares.`,`O nervo vago (X par craniano) é o principal responsável pela inervação simpática do coração.`,`As fibras pós-ganglionares parassimpáticas são longas e mielínicas.`,`O gânglio cervical craniano é parassimpático e inerva a glândula tireoide.`],resposta_correta:`A`,explicacao:`O sistema parassimpático utiliza acetilcolina (ACh) em ambas as sinapses — pré-ganglionar (nicotínico) e pós-ganglionar (muscarínico). A divisão simpática (opção B) usa ACh pré-ganglionar e noradrenalina pós-ganglionar. O nervo vago (opção C) é PARAssimpático e reduz a frequência cardíaca. As fibras pós-ganglionares parassimpáticas (opção D) são curtas e amielínicas. O gânglio cervical craniano (opção E) é SIMPÁTICO.`},{id:`fisio-010`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`enav`,topico:`cardiovascular`,subtopico:`Ciclo cardíaco`,dificuldade:`medio`,enunciado:`Sobre o ciclo cardíaco, assinale a alternativa que descreve corretamente a sequência de eventos:`,alternativas:[`Sístole atrial → Diástole ventricular → Sístole ventricular → Diástole atrial.`,`Diástole geral → Sístole atrial → Sístole ventricular → Diástole geral.`,`Sístole ventricular → Sístole atrial → Diástole ventricular → Diástole atrial.`,`Diástole atrial → Sístole ventricular → Sístole atrial → Diástole ventricular.`,`Sístole atrial → Sístole ventricular → Diástole atrial → Diástole ventricular.`],resposta_correta:`B`,explicacao:`O ciclo cardíaco inicia com a diástole geral (relaxamento de todas as câmaras), seguida pela sístole atrial (contração dos átrios, contribuindo com ~20% do enchimento ventricular), depois a sístole ventricular (contração dos ventrículos, ejeção do sangue) e finalmente a diástole geral novamente. A duração total do ciclo cardíaco a 75 bpm é de aproximadamente 0,8 segundos.`},{id:`fisio-011`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`cardiovascular`,subtopico:`Eletrocardiograma`,dificuldade:`dificil`,enunciado:`A respeito da interpretação do eletrocardiograma (ECG) em animais domésticos, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A onda P no ECG representa a despolarização atrial, o complexo QRS representa a despolarização ventricular, e o segmento ST representa o período em que ambos os ventrículos estão completamente despolarizados (platô do potencial de ação ventricular).`,explicacao:`A interpretação está correta: Onda P = despolarização atrial; Complexo QRS = despolarização ventricular; Segmento ST = ambos ventrículos despolarizados (platô); Onda T = repolarização ventricular. O intervalo PR (de P ao início de QRS) representa o atraso na condução pelo nó AV, essencial para o enchimento atrial antes da contração ventricular.`},{id:`fisio-012`,banca:`VUNESP`,ano:2019,prova:`VUNESP — Veterinário Prefeitura RJ 2019`,tipo:`concurso`,topico:`cardiovascular`,subtopico:`Pressão arterial`,dificuldade:`facil`,enunciado:`A pressão arterial sistêmica é determinada por fatores hemodinâmicos. A equação que relaciona a pressão arterial (PA) com o débito cardíaco (DC) e a resistência vascular periférica (RVP) é:`,alternativas:[`PA = DC + RVP`,`PA = DC × RVP`,`PA = DC / RVP`,`PA = DC² × RVP`,`PA = RVP / DC`],resposta_correta:`B`,explicacao:`A pressão arterial média (PAM) é determinada pela relação: PA = DC × RVP, onde DC (débito cardíaco) = volume sistólico × frequência cardíaca, e RVP (resistência vascular periférica) depende do calibre das arteríolas. Onde: DC é expresso em L/min e RVP em unidades de resistência (mmHg·min/L). Esta relação é fundamental para entender a fisiopatologia da hipertensão e do choque.`},{id:`fisio-013`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário Ministério Público 2023`,tipo:`concurso`,topico:`respiratorio`,subtopico:`Mecânica respiratória`,dificuldade:`medio`,enunciado:`A inspiração é um processo ativo que envolve a contração de músculos específicos. Em um cão em repouso, o principal músculo responsável pela inspiração é:`,alternativas:[`O músculo reto abdominal.`,`O diafragma.`,`O músculo intercostal interno.`,`O músculo transverso do abdome.`,`O músculo esquelético do pescoço.`],resposta_correta:`B`,explicacao:`O diafragma é o principal músculo inspiratório em mamíferos. Quando se contrai, desce e aumenta o volume torácico no eixo longitudinal, gerando pressão intratorácica negativa que permite a entrada de ar. Os músculos intercostais externos auxiliam na inspiração elevando as costelas. Em repouso, a expiração é passiva (elasticidade pulmonar). Os músculos abdominais (opções A e D) são expiratórios.`},{id:`fisio-014`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Residência em Patologia Animal 2021`,tipo:`residencia`,topico:`respiratorio`,subtopico:`Hemoglobina e transporte de gases`,dificuldade:`dificil`,enunciado:`A curva de dissociação da hemoglobina (Hb) é influenciada por diversos fatores. Assinale a alternativa que NÃO causa desvio da curva para a DIREITA:`,alternativas:[`Aumento da temperatura corporal.`,`Aumento da pressão parcial de CO₂ (efeito Bohr).`,`Aumento do 2,3-difosfoglicerato (2,3-DPG) eritrocitário.`,`Aumento do pH sanguíneo (alcalose).`,`Acidose metabólica.`],resposta_correta:`D`,explicacao:`O desvio da curva para a DIREITA indica DECREASE da afinidade da Hb pelo O₂ (facilita a liberação de O₂ nos tecidos). Fatores que desviam para a direita: ↑temperatura, ↑CO₂, ↑H⁺ (↓pH/acidose), ↑2,3-DPG. A ALCALOSE (↑pH, opção D) desvia a curva para a ESQUERDA, aumentando a afinidade da Hb pelo O₂ (prejudica a liberação tecidual).`},{id:`fisio-015`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`renal`,subtopico:`Filtração glomerular`,dificuldade:`medio`,enunciado:`A taxa de filtração glomerular (TFG) é um parâmetro fundamental da função renal. Sobre a TFG em cães, é CORRETO afirmar:`,alternativas:[`A TFG é determinada exclusivamente pela pressão hidrostática no capilar glomerular.`,`A TFG depende do balanço entre a pressão hidrostática capilar glomerular, a pressão oncótica e a pressão hidrostática capsular (de Bowman).`,`A albumina, por ser uma proteína de alto peso molecular, é livremente filtrada no glomérulo.`,`O clearance de inulina é considerado o método de referência para medir a TFG, pois a inulina é reabsorvida nos túbulos.`,`A TFG em cães adultos saudáveis é de aproximadamente 500 mL/min.`],resposta_correta:`B`,explicacao:`A TFG é determinada pela pressão de filtração líquida, que é o balanço entre: (1) Pressão hidrostática capilar glomerular (~60 mmHg, favorece filtração), (2) Pressão oncótica capilar (~32 mmHg, opõe) e (3) Pressão hidrostática capsular de Bowman (~18 mmHg, opõe). Pressão de filtração = 60 - 32 - 18 = ~10 mmHg. A albumina (opção C) NÃO é filtrada normalmente (peso molecular ~69.000 Da). A inulina (opção D) é filtrada mas NÃO reabsorvida (método de referência). A TFG canina (opção E) é ~3-5 mL/kg/min (~180-300 mL/min para um cão de 30 kg).`},{id:`fisio-016`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`renal`,subtopico:`Concentração de urina`,dificuldade:`dificil`,enunciado:`O mecanismo de concentração de urina no rim de mamíferos depende do sistema de contracorrente. Julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A alça de Henle descendente é permeável à água e impermeável a solutos, permitindo a reabsorção de água no córtex medular hipertônico. A porção ascendente é impermeável à água, mas transporta ativamente NaCl para o interstício, criando o gradiente osmótico medular necessário para a concentração urinária sob influência do ADH (vasopressina).`,explicacao:`O sistema de contracorrente renal é responsável pelo gradiente osmótico medular (hiperosmótico). A alça descendente perde água por osmose (permeável à água, impermeável a NaCl). A alça ascendente espessa transporta ativamente NaCl (pela Na⁺/K⁺/2Cl⁻ cotransporter, NKCC2), mas é impermeável à água, diluindo o fluido tubular e hipertonizando o interstício. O ADH atua nos ductos coletores, inserindo aquaporina-2 e permitindo a reabsorção de água final.`},{id:`fisio-017`,banca:`UNESP`,ano:2023,prova:`UNESP — Professor Adjunto Fisiologia 2023`,tipo:`concurso`,topico:`digestorio`,subtopico:`Ruminantes`,dificuldade:`dificil`,enunciado:`A fisiologia do rúmen é fundamental para a nutrição de ruminantes. Sobre a fermentação ruminal, assinale a alternativa INCORRETA:`,alternativas:[`Os ácidos graxos voláteis (AGV) — acetato, propionato e butirato — são os principais produtos da fermentação ruminal e fornecem até 70% da energia do ruminante.`,`O metano (CH₄) produzido no rúmen é um subproduto da fermentação que representa perda de energia e contribui para o efeito estufa.`,`O pH ruminal ideal para a fibrolítica é entre 6,2 e 6,8, sendo que valores abaixo de 5,5 causam acidose ruminal.`,`As bactérias celulolíticas do rúmen são estritamente anaeróbias e produzem celulase extracelular para degradar a fibra.`,`O rúmen absorve diretamente aminoácidos e glicose das dietas ricas em concentrado, sem necessidade de fermentação microbiana.`],resposta_correta:`E`,explicacao:`A alternativa E é INCORRETA. No rúmen, as proteínas dietéticas são degradadas em aminoácidos e depois em NH₃ (amônia) pelas bactérias proteolíticas. Os aminoácidos NÃO são absorvidos diretamente pelo rúmen. A glicose dietética é quase totalmente fermentada no rúmen. Os AGV (principalmente acetato, propionato e butirato) são absorvidos pela parede ruminal. A glicose sanguínea em ruminantes vem principalmente da gliconeogênese hepática a partir do propionato.`},{id:`fisio-018`,banca:`FCC`,ano:2019,prova:`FCC — Veterinário Prefeitura Campinas 2019`,tipo:`concurso`,topico:`digestorio`,subtopico:`Enzimas digestivas`,dificuldade:`medio`,enunciado:`Sobre as enzimas digestivas e seus respectivos locais de ação, assinale a alternativa CORRETA:`,alternativas:[`A pepsina é produzida no intestino delgado e atua em pH alcalino.`,`A tripsina é secretada pelo pâncreas na forma ativa (tripsina) e atua no estômago.`,`A lipase pancreática é secretada pelo pâncreas e atua no duodeno, necessitando da bile para emulsificação dos lipídeos.`,`A amilase salivar atua em pH ácido e destrói completamente o amido no estômago.`,`A lactase é produzida no estômago e quebra a lactose em glicose e galactose.`],resposta_correta:`C`,explicacao:`A lipase pancreática é secretada pelo pâncreas exócrino e atua no duodeno (pH ~7-8). Ela necessita da bile (ácidos biliares) para emulsificar os lipídeos em gotículas menores, aumentando a superfície de ação da enzima. A pepsina (opção A) é gástrica (pH ~2). A tripsina (opção B) é secretada como tripsinógeno (inativo) e ativada pela enteroquinase no duodeno. A amilase salivar (opção D) atua em pH ~7 e é inativada no estômago. A lactase (opção E) é produzida nas bordas em escova do intestino delgado.`},{id:`fisio-019`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`endocrino`,subtopico:`Hormônios tireoidianos`,dificuldade:`medio`,enunciado:`Sobre o eixo hipotálamo-hipófise-tireoide, assinale a alternativa CORRETA:`,alternativas:[`O TRH (hormônio liberador de tireotrofina) é produzido pela hipófise anterior e estimula a tireoide a produzir T3 e T4.`,`O TSH (hormônio tireoestimulante) é produzido pelo hipotálamo e atua nos receptores de T3 na tireoide.`,`A retroalimentação negativa dos hormônios tireoidianos (T3/T4) ocorre principalmente sobre o TRH hipotalâmico e o TSH hipofisário.`,`O T4 (tiroxina) é a forma biologicamente ativa do hormônio tireoidiano, enquanto o T3 é inativo.`,`O hipotálamo produz T3 e T4 diretamente, sem necessidade da tireoide.`],resposta_correta:`C`,explicacao:`A retroalimentação negativa (feedback negativo) é o mecanismo regulador do eixo: quando os níveis de T3/T4 estão altos, inibem a secreção de TRH no hipotálamo e de TSH na hipófise anterior. Quando baixos, há estímulo para produção de TRH → TSH → T3/T4. O TRH (opção A) é hipotalâmico. O TSH (opção B) é hipofisário. O T3 (opção D) é a forma ATIVA (3x mais potente que T4). O hipotálamo (opção E) produz TRH, não hormônios tireoidianos.`},{id:`fisio-020`,banca:`CESPE`,ano:2024,prova:`CESPE — Médico Veterinário IBAMA 2024`,tipo:`concurso`,topico:`endocrino`,subtopico:`Insulina e glucagon`,dificuldade:`dificil`,enunciado:`Sobre a regulação da glicemia pelos hormônios pancreáticos, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A insulina é secretada pelas células beta das ilhotas de Langerhans em resposta à hiperglicemia e promove a captação de glicose pelos tecidos periféricos (músculo esquelético e tecido adiposo), a glicogênese hepática e a lipogênese, enquanto inibe a glicogenólise, a gluconeogênese e a lipólise.`,explicacao:`A insulina é o principal hormônio hipoglicemiante. É secretada pelas células beta pancreáticas quando a glicemia sobe (>100 mg/dL). Seus efeitos anabólicos incluem: (1) captação de glicose (via GLUT4 em músculo/adiposo), (2) glicogênese hepática, (3) lipogênese, (4) síntese proteica. Inibe: glicogenólise, gluconeogênese, lipólise, cetogênese. O glucagon (células alfa) é o hormônio hiperglicemiante antagônico.`},{id:`fisio-021`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Prefeitura RJ 2022`,tipo:`concurso`,topico:`reprodutivo`,subtopico:`Ciclo estral`,dificuldade:`medio`,enunciado:`Sobre o ciclo estral de cadelas, assinale a alternativa CORRETA:`,alternativas:[`As cadelas são poliéstricas sazonais, com ciclos estrais regulares apenas durante a primavera.`,`O estro (cio) dura em média 9 dias e é caracterizado pela aceitação do macho e ovulação espontânea.`,`As cadelas ovulam apenas um oócito maduro, semelhante às mulheres.`,`O proestro dura em média 9 dias, com edema vulvar, sangramento e rejeição ao macho.`,`A ovulação em cadelas ocorre 48 horas após o pico de LH, com ovócitos imaturos que completam a maturação no oviduto.`],resposta_correta:`E`,explicacao:`Cadelas ovulam ovócitos IMATUROS (em estágio de ovócito primário — diplóteno). A ovulação ocorre ~48h após o pico de LH. Os ovócitos completam a primeira divisão meiótica no oviduto em ~48-72h pós-ovulação. Cadelas (opção A) são poliéstricas NÃO-sazonais (2 ciclos/ano). O estro (opção B) dura ~9 dias mas a ovulação é espontânea. Cadelas ovulam (opção C) múltiplos ovócitos. O proestro (opção D) dura ~9 dias com sangramento e rejeição ao macho (correto), mas a ovulação é espontânea em cadelas.`},{id:`fisio-022`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`hematologia`,subtopico:`Hemostasia`,dificuldade:`dificil`,enunciado:`A hemostasia é o processo que interrompe o sangramento e envolve mecanismos vasculares, plaquetários e da coagulação. Sobre a cascata de coagulação, assinale a alternativa CORRETA:`,alternativas:[`A via intrínseca é ativada pelo fator tecidual (FT) e fator VII, e a via extrínseca é ativada pelo contato do sangue com superfícies estranhas.`,`A via intrínseca é ativada pelo contato do sangue com colágeno subendotelial (fator XII), e a via extrínseca é ativada pelo fator tecidual (FT) e fator VII.`,`O fibrinogênio é convertido em fibrina pela trombina, e o fator XIII estabiliza a malha de fibrina através de ligações covalentes.`,`As plaquetas aderem ao local da lesão vascular apenas por interação com o colágeno, sem participação de fator de von Willebrand.`,`A vitamina K é necessária para a síntese dos fatores V, VIII e XI da coagulação.`],resposta_correta:`C`,explicacao:`A trombina (fator IIa) converte o fibrinogênio (solúvel) em monômeros de fibrina (insolúvel). O fator XIIIa (ativado por trombina) catalisa ligações covalentes cruzadas entre os monômeros de fibrina, estabilizando o coágulo. A via intrínseca (opção A/B) é ativada pelo contato com superfícies estranhas (fator XII). A via extrínseca é ativada por FT + fVII. O fator de von Willebrand (opção D) é essencial para adesão plaquetária. A vitamina K (opção E) é necessária para fatores II, VII, IX, X (e proteínas C e S).`},{id:`fisio-023`,banca:`CRMV`,ano:2021,prova:`CRMV — Exame de Qualificação 2021`,tipo:`crmv`,topico:`termorregulação`,subtopico:`Homeotermia`,dificuldade:`facil`,enunciado:`Os animais domésticos são classificados quanto à regulação da temperatura corporal. Assinale a alternativa que descreve corretamente:`,alternativas:[`Aves e mamíferos são heterotermos, pois mantêm temperatura corporal constante independentemente da temperatura ambiental.`,`Répteis são animais homeotermos, pois regulam sua temperatura por mecanismos comportamentais e metabólicos.`,`Cães e gatos são homeotermos, mas dependem exclusivamente de mecanismos evaporativos (ofegar) para dissipar calor, não possuindo sudorese eficiente.`,`Animais homeotermos não possuem mecanismos de termogênese e dependem exclusivamente do ambiente para aquecimento.`,`O hipotálamo anterior é o único centro termorregulador, atuando exclusivamente na produção de calor.`],resposta_correta:`C`,explicacao:`Cães e gatos são homeotermos (temperatura corporal constante ~38-39°C). Para dissipar calor, dependem principalmente do ofegar (evaporação pelas vias respiratórias), pois possuem glândulas sudoríparas apenas nas almofadas digitais (insuficientes para termorregulação). Aves e mamíferos (opção A) são homeotermos, não heterotermos. Répteis (opção B) são heterotermos (pecilotermos). Os animais homeotermos (opção D) possuem termogênese (tremor, termogênese sem tremor). O hipotálamo (opção E) possui centros de calor E frio.`},{id:`fisio-024`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência em Clínica de Ruminantes 2022`,tipo:`residencia`,topico:`metabolismo`,subtopico:`Metabolismo energético`,dificuldade:`dificil`,enunciado:`Em vacas leiteiras no pico de lactação, a demanda energética para a síntese de leite supera frequentemente a ingestão de energia da dieta. Assinale a alternativa que descreve corretamente o metabolismo energético nessa condição:`,alternativas:[`O balanço energético negativo (BEN) estimula a lipogênese no tecido adiposo e o armazenamento de gordura.`,`O BEN mobiliza reservas de gordura corporal (lipólise), aumentando os ácidos graxos não esterificados (AGNE) no sangue, que são oxidados no fígado, produzindo corpos cetônicos.`,`A cetose clínica ocorre exclusivamente por excesso de glicose no sangue, sem relação com a mobilização de gordura.`,`O propionato ruminal é o principal precursor de glicose sanguínea em ruminantes, mas não tem papel na cetogênese.`,`O fígado de ruminantes converte AGNE em lipoproteínas de baixa densidade (VLDL) de forma muito eficiente, prevenindo a cetose.`],resposta_correta:`B`,explicacao:`No BEN (comum em vacas de alta produção no pico de lactação), o organismo mobiliza gordura corporal (lipólise), liberando AGNE (ácidos graxos não esterificados) no sangue. O fígado oxida os AGNE em corpos cetônicos (β-hidroxibutirato, acetoacetato, acetona). Quando a produção de corpos cetônicos excede a capacidade de utilização, ocorre cetose. O propionato (opção D) é o principal precursor de glicose via gliconeogênese hepática. O fígado de ruminantes (opção E) tem capacidade LIMITADA de produzir VLDL, o que predispõe ao fígado gorduroso.`},{id:`fisio-025`,banca:`ENAV`,ano:2018,prova:`ENAV — Concurso 2018`,tipo:`enav`,topico:`lactação`,subtopico:`Galactopoiese`,dificuldade:`medio`,enunciado:`A lactação é regulada por hormônios que atuam em diferentes fases. Sobre a galactopoiese (manutenção da produção de leite), assinale a alternativa CORRETA:`,alternativas:[`A ocitocina é responsável pela síntese dos componentes do leite nas células epiteliais da glândula mamária.`,`A prolactina é responsável pela ejeção do leite (reflexo de descida) ao contrair as células mioepiteliais.`,`O hormônio do crescimento (GH/somatotrofina) atua como galactopoietico, aumentando a produção de leite sem efeitos metabólicos adversos.`,`A prolactina é o principal hormônio galactopoietico, estimulando a síntese de proteínas do leite, lactose e gordura nas células epiteliais.`,`O cortisol (glicocorticoide) não tem papel na lactação, sendo exclusivamente catabólico.`],resposta_correta:`D`,explicacao:`A prolactina é o principal hormônio galactopoietico (mantenedora da produção de leite). Atua nas células epiteliais da glândula mamária estimulando a síntese de caseína, α-lactalbumina (enzima da síntese de lactose), e gordura do leite. A ocitocina (opção A/B) é responsável pela EJEÇÃO do leite (contração mioepitelial), não pela síntese. O GH (opção C) tem efeito galactopoietico mas causa resistência insulínica. O cortisol (opção E) é necessário para a diferenciação das células mamárias (junto com insulina e prolactina).`},{id:`fisio-026`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista Ministério Agricultura 2023`,tipo:`concurso`,topico:`imunológico`,subtopico:`Imunidade inata`,dificuldade:`medio`,enunciado:`Sobre os mecanismos de imunidade inata em animais domésticos, julgue o item:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`B`,vf:!0,vf_texto:`As células NK (Natural Killer) são células da imunidade ADAPTATIVA que reconhecem antígenos específicos através de receptores de células T (TCR) e produzem anticorpos contra células infectadas por vírus.`,explicacao:`O item é FALSO. As células NK são da imunidade INATA, NÃO adaptativa. Elas NÃO possuem TCR nem produzem anticorpos. As células NK reconhecem células que perderam a expressão de MHC-I (mecanismo de "missing self") e as eliminam por citotoxicidade direta (perforinas e granzimas). São importantes na defesa antiviral e antitumoral. Os anticorpos são produzidos por linfócitos B (plasmócitos), que são da imunidade adaptativa.`},{id:`fisio-027`,banca:`UFMT`,ano:2021,prova:`UFMT — Residência em Equinos 2021`,tipo:`residencia`,topico:`exercício`,subtopico:`Fisiologia do exercício equino`,dificuldade:`dificil`,enunciado:`Cavalos atletas possuem adaptações fisiológicas únicas para o exercício de alta intensidade. Assinale a alternativa que descreve corretamente:`,alternativas:[`Os cavalos possuem baça (baço) que armazena até 12 litros de eritrócitos, que são mobilizados durante o exercício intenso, aumentando a capacidade de transporte de oxigênio.`,`Os cavalos são exclusivamente anaeróbios durante o exercício, não utilizando o metabolismo oxidativo.`,`A acidose láctica durante o exercício intenso em cavalos é causada exclusivamente por insuficiência respiratória.`,`Os cavalos não possuem mioglobina no músculo esquelético, dependendo exclusivamente da hemoglobina sanguínea.`,`A frequência cardíaca máxima de cavalos em exercício é de aproximadamente 80 bpm.`],resposta_correta:`A`,explicacao:`Cavalos possuem uma adaptação única: o baço (baça) armazena grande volume de eritrócitos (~12 L em cavalos de 500 kg). Durante o exercício, a contração esplênica (mediada por catecolaminas) libera esses eritrócitos na circulação, aumentando o hematórito de ~35% para ~55-65% e a capacidade de transporte de O₂. Cavalos (opção B) utilizam metabolismo aeróbio E anaeróbio. A acidose (opção C) é multifatorial. Cavalos possuem mioglobina (opção D) abundante (músculo vermelho). A FC máxima (opção E) é ~200-240 bpm.`},{id:`fisio-028`,banca:`ENAV`,ano:2017,prova:`ENAV — Concurso 2017`,tipo:`enav`,topico:`celular`,subtopico:`Receptores celulares`,dificuldade:`medio`,enunciado:`Os receptores celulares são proteínas que medeiam a ação de hormônios e neurotransmissores. Sobre os tipos de receptores, é CORRETO afirmar:`,alternativas:[`Receptores de membrana do tipo ionotrópicos são canais iônicos que abrem quando o ligante se liga, permitindo fluxo iônico rápido.`,`Receptores nucleares são ativados por neurotransmissores como acetilcolina e noradrenalina.`,`Receptores metabotrópicos são canais iônicos que respondem diretamente à voltagem da membrana.`,`Os receptores de tirosina quinase são exclusivos de células procariotas.`,`Os receptores acoplados a proteína G (GPCR) ativam exclusivamente a via do AMP cíclico.`],resposta_correta:`A`,explicacao:`Receptores ionotrópicos são canais iônicos que abrem diretamente quando o ligante se liga, permitindo fluxo iônico rápido (milissegundos). Exemplos: receptor nicotínico de ACh (canal Na⁺/K⁺), receptor GABA_A (canal Cl⁻), receptor NMDA (canal Ca²⁺/Na⁺). Receptores nucleares (opção B) respondem a hormônios lipossolúveis (T3, cortisol, estrógeno). Metabotrópicos (opção C) usam segundos mensageiros. Receptores de tirosina quinase (opção D) são para insulina, fatores de crescimento. GPCR (opção E) ativam múltiplas vias (AMPc, IP3/DAG, Ca²⁺).`},{id:`fisio-029`,banca:`FCC`,ano:2020,prova:`FCC — Veterinário CETESB 2020`,tipo:`concurso`,topico:`nervoso`,subtopico:`Dor e analgesia`,dificuldade:`medio`,enunciado:`A nocicepção (percepção da dor) envolve vias neurais específicas. Sobre o sistema de dor, assinale a alternativa CORRETA:`,alternativas:[`As fibras C são fibras mielínicas de condução rápida que transmitem a dor aguda e bem localizada.`,`As fibras Aδ são fibras amielínicas de condução lenta que transmitem a dor crônica e difusa.`,`A substância P é um neuropeptídeo liberado pelas terminações nociceptivas que medeia a transmissão sináptica da dor na medula espinhal.`,`O sistema de modulação da dor de Melzack e Wall propõe que a estimulação de fibras Aβ (tato) inibe a transmissão da dor (teoria do portão).`,`A endorfina é um neurotransmissor excitatório que amplifica a percepção da dor.`],resposta_correta:`C`,explicacao:`A substância P é um neuropeptídeo (11 aminoácidos) liberado pelas terminações das fibras C e Aδ nos cornos dorsais da medula espinhal, mediando a transmissão sináptica da nocicepção. As fibras C (opção A) são AMIELÍNICAS e lentas (dor crônica/difusa). As fibras Aδ (opção B) são POUCO mielínicas e rápidas (dor aguda/localizada). A teoria do portão (opção D) está CORRETA na descrição mas a alternativa C é mais precisa. As endorfinas (opção E) são INIBITÓRIAS (analgésicas naturais).`},{id:`fisio-030`,banca:`ENAV`,ano:2016,prova:`ENAV — Concurso 2016`,tipo:`enav`,topico:`respiratorio`,subtopico:`Ventilação e perfusão`,dificuldade:`dificil`,enunciado:`A relação ventilação/perfusão (V/Q) é essencial para a eficiência das trocas gasosas pulmonares. Assinale a alternativa que descreve corretamente:`,alternativas:[`A relação V/Q é uniforme em todos os segmentos pulmonares, tanto em posição ortostática quanto em decúbito.`,`No ápice pulmonar, a ventilação é maior que a perfusão, resultando em V/Q > 1 (espaço morto fisiológico).`,`Na base pulmonar, a perfusão é maior que a ventilação, resultando em V/Q < 1 (shunt fisiológico).`,`Em um pulmão com obstrução brônquica completa, a V/Q é igual a zero (shunt verdadeiro).`,`A hipóxia alveolar causada por V/Q baixo provoca vasoconstrição pulmonar local (hipóxia pulmonar), redirecionando o sangue para áreas melhor ventiladas.`],resposta_correta:`E`,explicacao:`A vasoconstrição pulmonar hipóxica (HPV — Hypoxic Pulmonary Vasoconstriction) é um mecanismo único da circulação pulmonar: quando um alvéolo está hipóxico (V/Q baixo), as arteríolas pulmonares adjacentes se contraem, redirecionando o sangue para áreas melhor ventiladas. Isso otimiza a eficiência das trocas gasosas. O ápice (opção B) tem V/Q alto (~3.3) e a base (opção C) tem V/Q baixo (~0.6) — correto, mas a descrição de "espaço morto" e "shunt" é simplificada. V/Q = 0 (opção D) ocorre em atelectasia completa.`},{id:`fisio-031`,banca:`UNESP`,ano:2021,prova:`UNESP — Residência em Patologia 2021`,tipo:`residencia`,topico:`celular`,subtopico:`Organelas celulares`,dificuldade:`medio`,enunciado:`A respeito das organelas celulares e suas funções, assinale a alternativa CORRETA:`,alternativas:[`As mitocôndrias possuem DNA próprio, membrana dupla e são responsáveis pela fosforilação oxidativa, produzindo a maior parte do ATP celular.`,`O retículo endoplasmático rugoso (RER) é responsável pela síntese de lipídeos e não possui ribossomos aderidos à sua membrana.`,`O complexo de Golgi é responsável exclusivamente pela degradação de proteínas defeituosas através de proteases internas.`,`Os lisossomos possuem pH alcalino em seu interior para ativarem suas hidrolases ácidas.`,`Os peroxissomos são organelas exclusivas de células vegetais e não participam do metabolismo de ácidos graxos em células animais.`],resposta_correta:`A`,explicacao:`As mitocôndrias possuem DNA próprio (circular, herdado maternamente), membrana dupla (externa e interna com cristas) e são o sítio da fosforilação oxidativa e do ciclo de Krebs, produzindo ~34 moléculas de ATP por glicose. O RER (opção B) possui ribossomos aderidos e sintetiza proteínas. O complexo de Golgi (opção C) modifica, empacota e direciona proteínas. Os lisossomos (opção D) possuem pH ácido (~4,5-5,0). Os peroxissomos (opção E) estão presentes em células animais e degradam ácidos graxos de cadeia muito longa.`},{id:`fisio-032`,banca:`FCC`,ano:2018,prova:`FCC — Veterinário IBAMA 2018`,tipo:`concurso`,topico:`celular`,subtopico:`Ciclo celular`,dificuldade:`dificil`,enunciado:`Sobre o ciclo celular e seus pontos de controle, assinale a alternativa CORRETA:`,alternativas:[`O ponto de restrição (ponto R) na fase G1 verifica se a célula tem tamanho adequado, nutrientes suficientes e DNA íntegro antes de comprometer-se com a replicação.`,`A fase S é caracterizada pela divisão do núcleo celular (cariocinese) e separação dos cromossomos.`,`Os complexos ciclina-CDK atuam apenas na fase M e não participam das fases G1 e S.`,`O checkpoint da transição G2/M verifica apenas o tamanho celular, sem avaliar a integridade do DNA.`,`A mitose é a fase mais longa do ciclo celular, durando aproximadamente 90% do tempo total.`],resposta_correta:`A`,explicacao:`O ponto de restrição (R) em G1 é um ponto de decisão crucial onde a célula avalia: (1) sinais mitogênicos, (2) disponibilidade de nutrientes, (3) tamanho celular e (4) integridade do DNA. Se as condições forem favoráveis, a célula entra na fase S (síntese de DNA). As ciclinas-CDK (opção C) atuam em TODAS as fases do ciclo. O checkpoint G2/M (opção D) verifica principalmente se a replicação do DNA foi completada com fidelidade. A interfase (G1+S+G2) é a fase mais longa (~90%), e a mitose (opção E) é relativamente rápida (~1 hora).`},{id:`fisio-033`,banca:`CESPE`,ano:2019,prova:`CESPE — Analista MAPA 2019`,tipo:`concurso`,topico:`celular`,subtopico:`Apoptose`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre apoptose celular:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A apoptose é um processo de morte celular programada que ocorre sem inflamação, envolvendo ativação de caspases, condensação da cromatina, fragmentação do DNA internucleossomal e formação de corpos apoptóticos que são fagocitados por macrófagos.`,explicacao:`A apoptose é uma morte celular genética e programada, distinta da necrose. Características: (1) ativação de caspases (cisteíno-proteases), (2) condensação da cromatina, (3) fragmentação do DNA em múltiplos de ~180 pb (escada de DNA), (4) formação de bolhas na membrana (zeiose) e corpos apoptóticos, (5) preservação da integridade da membrana (sem inflamação), (6) fagocitose rápida. Diferente da necrose, que é passiva, desordenada e causa inflamação.`},{id:`fisio-034`,banca:`VUNESP`,ano:2017,prova:`VUNESP — Veterinário Concurso Municipal 2017`,tipo:`concurso`,topico:`celular`,subtopico:`Mitose`,dificuldade:`facil`,enunciado:`As fases da mitose ocorrem em sequência. Assinale a alternativa que apresenta a sequência CORRETA:`,alternativas:[`Telófase → Anáfase → Metáfase → Prófase`,`Prófase → Metáfase → Anáfase → Telófase`,`Metáfase → Prófase → Telófase → Anáfase`,`Anáfase → Telófase → Prófase → Metáfase`,`Prófase → Anáfase → Metáfase → Telófase`],resposta_correta:`B`,explicacao:`A mitose ocorre em quatro fases: (1) Prófase — condensação dos cromossomos, desaparecimento do nucléolo e formação do fuso mitótico; (2) Metáfase — cromossomos alinhados na placa equatorial; (3) Anáfase — separação das cromátides-irmãs que migram para os polos; (4) Telófase — descondensação cromossômica, reorganização do envelope nuclear e citocinese. A mitose produz duas células-filhas geneticamente idênticas à célula-mãe (2n → 2n).`},{id:`fisio-035`,banca:`UFMG`,ano:2020,prova:`UFMG — Residência em Reprodução Animal 2020`,tipo:`residencia`,topico:`celular`,subtopico:`Meiose`,dificuldade:`medio`,enunciado:`A meiose é o processo de divisão celular essencial para a gametogênese. Sobre a meiose, é CORRETO afirmar:`,alternativas:[`A meiose produz quatro células-filhas geneticamente idênticas à célula-mãe, todas diplóides.`,`O crossing-over (permutação) ocorre na prófase I e é responsável pela recombinação genética entre cromossomos homólogos.`,`A segregação independente dos cromossomos ocorre na anáfase II e gera variabilidade genética.`,`Na meiose II, há separação de cromossomos homólogos, semelhante à mitose convencional.`,`A meiose ocorre em todas as células somáticas do organismo adulto.`],resposta_correta:`B`,explicacao:`O crossing-over ocorre na prófase I (estágio de paquíteno), quando cromossomos homólogos trocam segmentos de DNA nas quiasmas. Isso é o principal mecanismo de recombinação genética, gerando diversidade. A meiose produz 4 células HAPLOIDES (n), geneticamente distintas (opção A). A segregação independente (opção C) ocorre na anáfase I. Na meiose II (opção D), há separação de cromátides-irmãs. A meiose (opção E) ocorre apenas em células germinativas.`},{id:`fisio-036`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`celular`,subtopico:`Organelas celulares`,dificuldade:`facil`,enunciado:`Sobre os ribossomos, assinale a alternativa CORRETA:`,alternativas:[`Os ribossomos são organelas membranosas que sintetizam lipídeos no retículo endoplasmático liso.`,`Os ribossomos são compostos por RNA ribossomal (rRNA) e proteínas, e são responsáveis pela síntese de proteínas (tradução).`,`Os ribossomos livres no citoplasma produzem exclusivamente proteínas de exportação (secretadas).`,`Os ribossomos possuem membrana simples que os envolve, separando-os do citoplasma.`,`Os ribossomos são encontrados apenas em células eucariotas e ausentes em procariotas.`],resposta_correta:`B`,explicacao:`Os ribossomos são complexos de rRNA e proteínas, sem membrana, responsáveis pela tradução (síntese proteica). São constituídos por subunidades grande e pequena. Em eucariotas (80S), encontram-se livres no citoplasma (sintetizam proteínas intracelulares) ou aderidos ao RER (sintetizam proteínas de membrana e secretadas). Em procariotas (70S), são menores. Mitocôndrias e cloroplastos possuem ribossomos próprios (70S).`},{id:`fisio-037`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`nervoso`,subtopico:`Medula espinhal`,dificuldade:`medio`,enunciado:`A medula espinhal é o principal centro de integração de reflexos espinhais. Sobre a organização da substância cinzenta medular, assinale a alternativa CORRETA:`,alternativas:[`Os cornos dorsais (posterior) contêm neurônios motores que inervam a musculatura esquelética.`,`Os cornos ventrais (anterior) contêm neurônios sensoriais aferentes que chegam pelos nervos espinhais.`,`Os cornos dorsais contêm neurônios sensoriais de segunda ordem que recebem aferências nociceptivas e proprioceptivas.`,`A substância branca medular é composta exclusivamente por corpos celulares de neurônios.`,`O canal central da medula espinhal contém líquido cefalorraquidiano apenas em fetos, desaparecendo no adulto.`],resposta_correta:`C`,explicacao:`Os cornos dorsais da medula espinhal contêm neurônios de segunda ordem que recebem aferências sensoriais (dor, temperatura, tato, propriocepção) dos neurônios de primeira ordem nos gânglios das raízes dorsais. Os cornos ventrais (opção A) contêm os neurônios motores (alfa e gama). Os neurônios sensoriais aferentes (opção B) têm corpos celulares no gânglio da raiz dorsal, não nos cornos. A substância branca (opção D) contém axônios mielinizados. O canal central (opção E) persiste no adulto, contendo LCR.`},{id:`fisio-038`,banca:`CESPE`,ano:2021,prova:`CESPE — Médico Veterinário MAPA 2021`,tipo:`concurso`,topico:`nervoso`,subtopico:`Tronco encefálico`,dificuldade:`dificil`,enunciado:`Julgue o item a seguir sobre o tronco encefálico:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A formação reticular do tronco encefálico contém centros vitais para a regulação do ciclo sono-vigília, da respiração e da pressão arterial, sendo que lesões no bulbo podem causar parada respiratória e cardiovascular.`,explicacao:`A formação reticular é uma rede de neurônios no tronco encefálico (bulbo, ponte e mesencéfalo) que regula funções vitais: (1) centro respiratório bulbar (ritmo respiratório), (2) centro cardiovascular (vasomotor — regula PA e FC), (3) sistema reticular ativador ascendente (SRAA — mantém o estado de vigília). Lesões bulbares podem ser fatais por parada respiratória e cardiovascular. O bulbo também contém reflexos vitais como tosse, vômito e deglutição.`},{id:`fisio-039`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Residência em Clínica de Pequenos Animais 2022`,tipo:`residencia`,topico:`nervoso`,subtopico:`Cerebelo`,dificuldade:`medio`,enunciado:`O cerebelo é essencial para a coordenação motora e o equilíbrio. Sobre as funções cerebelares, assinale a alternativa CORRETA:`,alternativas:[`O cerebelo é responsável pela iniciação voluntária dos movimentos, substituindo o córtex motor.`,`O cerebelo recebe aferências proprioceptivas (fusos musculares, órgãos tendinosos de Golgi) e vestibulares para coordenar movimentos e manter a postura.`,`O cerebelo controla exclusivamente funções viscerais autônomas, como a frequência cardíaca e a pressão arterial.`,`Lesões cerebelares causam paralisia flácida dos membros, sem alteração da coordenação.`,`O cerebelo não possui conectividade com o córtex cerebral e opera de forma isolada.`],resposta_correta:`B`,explicacao:`O cerebelo coordena movimentos e mantém a postura e o equilíbrio recebendo: (1) aferências proprioceptivas (informação sobre posição e movimento dos músculos e articulações), (2) aferências vestibulares (equilíbrio), (3) aferências corticais (cópia do comando motor — eferência copia). Lesões cerebelares causam ataxia, dismetria, tremor intencional e hipotonia, NÃO paralisia (opção D). O cerebelo (opção A) NÃO inicia movimentos.`},{id:`fisio-040`,banca:`VUNESP`,ano:2019,prova:`VUNESP — Veterinário Concurso Estadual 2019`,tipo:`concurso`,topico:`nervoso`,subtopico:`Sistema límbico`,dificuldade:`medio`,enunciado:`O sistema límbico está envolvido com emoções, memória e comportamento. Assinale a estrutura que NÃO faz parte do sistema límbico:`,alternativas:[`Hipocampo — essencial para a formação de memórias de longo prazo.`,`Amígdala cerebral — envolvida com respostas de medo e agressividade.`,`Córtex cingulado — participa da regulação emocional e motivação.`,`Cerebelo — principal centro de coordenação motora e equilíbrio.`,`Corpo mamilar — participa do circuito de Papez para a memória.`],resposta_correta:`D`,explicacao:`O cerebelo NÃO faz parte do sistema límbico. É responsável pela coordenação motora, equilíbrio e aprendizado motor. O sistema límbico inclui: hipocampo (memória), amígdala (emoções — medo, agressividade), córtex cingulado (regulação emocional), corpos mamilares (circuito de Papez), septo, giro do cíngulo e hipotálamo. O circuito de Papez conecta hipocampo → corpos mamilares → tálamo anterior → córtex cingulado → hipocampo.`},{id:`fisio-041`,banca:`CRMV`,ano:2020,prova:`CRMV — Exame de Qualificação 2020`,tipo:`crmv`,topico:`nervoso`,subtopico:`Sono e vigília`,dificuldade:`medio`,enunciado:`Sobre o ciclo sono-vigília em mamíferos domésticos, assinale a alternativa CORRETA:`,alternativas:[`O sono REM (movimentos oculares rápidos) é caracterizado por atividade cerebral de alta frequência e baixa amplitude, atonia muscular e movimentos oculares rápidos.`,`O sono NREM é caracterizado exclusivamente por atividade elétrica cerebral de alta amplitude e baixa frequência (ondas delta), sem alterações musculares.`,`A melatonina é produzida pela hipófise anterior e atua como o principal hormônio indutor de vigília.`,`Os gatos dormem em média 4 horas por dia, sendo os mamíferos domésticos que menos dormem.`,`O hipotálamo posterior contém neurônios orexígenos que promovem exclusivamente a vigília, sem papel no sono.`],resposta_correta:`A`,explicacao:`O sono REM (paradoxal) é caracterizado por: (1) EEG de alta frequência e baixa amplitude (atividade cortical intensa — sonhos), (2) atonia muscular (paralisia temporária — ativação inibitória bulbar), (3) movimentos oculares rápidos, (4) irregularidade respiratória e cardíaca. A melatonina (opção C) é produzida pela glândula pineal (epífise) e induz o SONO. Cães dormem ~12-14h e gatos ~12-16h (opção D). O hipotálamo lateral (opção E) contém neurônios orexígenos (hipocretina/orexina) que promovem vigília.`},{id:`fisio-042`,banca:`UNESP`,ano:2022,prova:`UNESP — Professor Adjunto Fisiologia 2022`,tipo:`concurso`,topico:`muscular`,subtopico:`Tipos de fibra muscular`,dificuldade:`medio`,enunciado:`As fibras musculares esqueléticas são classificadas em tipos distintos quanto ao metabolismo e velocidade de contração. Assinale a alternativa CORRETA:`,alternativas:[`As fibras do tipo I (lentas oxidativas) são brancas, possuem poucas mitocôndrias e são recrutadas em exercícios de curta duração e alta intensidade.`,`As fibras do tipo IIb (rápidas glicolíticas) são vermelhas, ricas em mioglobina e capazes de contração sustentada por longos períodos.`,`As fibras do tipo I (lentas oxidativas) são vermelhas, ricas em mioglobina e mitocôndrias, resistentes à fadiga, sendo recrutadas em exercícios de longa duração.`,`As fibras do tipo IIa são exclusivamente glicolíticas e não possuem capacidade oxidativa.`,`A distribuição dos tipos de fibra é idêntica em todas as raças caninas, independentemente do perfil de atividade.`],resposta_correta:`C`,explicacao:`As fibras tipo I (lentas/oxidativas) são vermelhas (rica em mioglobina e citocromos), com muitas mitocôndrias e capilares, resistentes à fadiga. São recrutadas em contrações sustentadas (postura, maratona). As fibras tipo IIb (opção A/B) são brancas, glicolíticas, rápidas, mas fadigam rapidamente. As fibras tipo IIa (opção D) são intermediárias (oxidativas-glicolíticas). A distribuição de fibras (opção E) varia com a raça, espécie e treinamento (ex.: cães Greyhound têm mais fibras IIb).`},{id:`fisio-043`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`muscular`,subtopico:`Contração muscular`,dificuldade:`facil`,enunciado:`A teoria dos filamentos deslizantes explica o mecanismo da contração muscular. Assinale a alternativa que descreve corretamente o papel do cálcio na contração:`,alternativas:[`O cálcio é liberado do retículo sarcoplasmático e liga-se à tropomiosina, permitindo a interação actina-miosina.`,`O cálcio é liberado do retículo sarcoplasmático e liga-se à troponina C, deslocando a tropomiosina e expondo os sítios de ligação da miosina na actina.`,`O cálcio é captado pelo retículo sarcoplasmático durante a contração, promovendo o encurtamento sarcômero.`,`O cálcio atua exclusivamente na transmissão sináptica da placa motora, sem papel direto na contração.`,`A miosina liga-se diretamente à actina sem necessidade de cálcio em fibras esqueléticas.`],resposta_correta:`B`,explicacao:`Na contração muscular: (1) Potencial de ação → liberação de Ca²⁺ do retículo sarcoplasmático via canais de rianodina; (2) Ca²⁺ liga-se à troponina C (no complexo troponina da actina); (3) Conformação da troponina muda, deslocando a tropomiosina; (4) Sítios de ligação da miosina na actina ficam expostos; (5) Pontes cruzadas se formam (miosina-actina); (6) Ciclo de pontes cruzadas → contração. A tropomiosina (opção A) NÃO liga Ca²⁺ diretamente.`},{id:`fisio-044`,banca:`UFBA`,ano:2021,prova:`UFBA — Residência em Clínica de Grandes Animais 2021`,tipo:`residencia`,topico:`muscular`,subtopico:`Fadiga muscular`,dificuldade:`medio`,enunciado:`A fadiga muscular é a redução transitória da capacidade de gerar força. Sobre os mecanismos de fadiga, assinale a alternativa CORRETA:`,alternativas:[`A fadiga muscular é causada exclusivamente pelo acúmulo de ácido lático no músculo, sem envolvimento de outros fatores.`,`A fadiga pode ocorrer tanto no sistema nervoso central (fadiga central) quanto no músculo (fadiga periférica), envolvendo depleção de ATP e fosfocreatina e acúmulo de H⁺ e Pi.`,`O acúmulo de potássio no fluido intersticial durante o exercício intenso não contribui para a fadiga muscular.`,`A fadiga muscular é irreversível e causa dano permanente às miofibrilas.`,`A fadiga afeta exclusivamente fibras do tipo I (lentas), enquanto as fibras tipo II (rápidas) são imunes à fadiga.`],resposta_correta:`B`,explicacao:`A fadiga muscular tem componentes centrais (SNC — redução do comando motor) e periféricos (músculo). Na fadiga periférica: depleção de fosfocreatina (PCr), redução de ATP, acúmulo de H⁺ (↓pH — acidose), acúmulo de fosfato inorgânico (Pi), acúmulo de K⁺ intersticial e disfunção do retículo sarcoplasmático. O ácido lático (opção A) é convertido em lactato, que é reciclado (ciclo de Cori). A fadiga (opção D) é reversível com repouso.`},{id:`fisio-045`,banca:`FCC`,ano:2023,prova:`FCC — Veterinário Concurso Público 2023`,tipo:`concurso`,topico:`muscular`,subtopico:`Músculo liso`,dificuldade:`medio`,enunciado:`O músculo liso difere do músculo esquelético em diversos aspectos. Assinale a alternativa que descreve corretamente uma característica do músculo liso:`,alternativas:[`O músculo liso possui estrias transversais visíveis ao microscópio devido à organização regular de actina e miosina em sarcômeros.`,`A contração do músculo liso é regulada pelo complexo Ca²⁺-calmodulina e pela quinase da cadeia leve de miosina (MLCK), sem envolvimento de troponina.`,`O músculo liso possui junções neuromusculares tipo placa motora, idênticas às do músculo esquelético.`,`A contração do músculo liso é rápida e de curta duração, semelhante à das fibras esqueléticas tipo IIb.`,`O músculo liso não possui capacidade de contração sem inervação nervosa, cessando imediatamente após a denervação.`],resposta_correta:`B`,explicacao:`No músculo liso, o Ca²⁺ liga-se à calmodulina (não à troponina, que é ausente). O complexo Ca²⁺-calmodulina ativa a MLCK, que fosforifica a cadeia leve de miosina, permitindo a interação actina-miosina. O músculo liso (opção A) é NÃO-estriado (sem sarcômeros organizados). Não possui placa motora clássica (opção C). A contração é lenta e sustentada (opção D). O músculo liso (opção E) mantém tônus basal mesmo sem inervação (miogênico).`},{id:`fisio-046`,banca:`AVAMEC`,ano:2018,prova:`AVAMEC — Prova de Título em Cardiologia Veterinária 2018`,tipo:`concurso`,topico:`muscular`,subtopico:`Músculo cardíaco`,dificuldade:`medio`,enunciado:`O miocárdio possui características únicas que permitem a contração cardíaca coordenada. Assinale a alternativa CORRETA:`,alternativas:[`Os cardiomiócitos são células multinucleadas, semelhantes às fibras musculares esqueléticas.`,`Os discos intercalares contêm junções comunicantes (gap junctions) que permitem a propagação elétrica rápida entre cardiomiócitos, funcionando como um sincício funcional.`,`O músculo cardíaco depende exclusivamente de inervação autônoma para iniciar cada batimento, sem capacidade de automação.`,`Os cardiomiócitos possuem poucas mitocôndrias e dependem predominantemente do metabolismo anaeróbio.`,`O músculo cardíaco é insensível a variações na concentração de cálcio extracelular.`],resposta_correta:`B`,explicacao:`Os discos intercalares são estruturas especializadas entre cardiomiócitos adjacentes que contêm: (1) junções comunicantes (gap junctions) — permitem a passagem direta de íons e potencial de ação entre células, criando um sincício funcional; (2) desmossomos e aderências firmes — mantêm a coesão mecânica. Os cardiomiócitos (opção A) geralmente possuem 1-2 núcleos. O coração (opção C) possui automação (nó SA — marca-passo). Miocárdio (opção D) é rico em mitocôndrias (~35% do volume — metabolismo aeróbio).`},{id:`fisio-047`,banca:`CESPE`,ano:2018,prova:`CESPE — Médico Veterinário IBAMA 2018`,tipo:`concurso`,topico:`muscular`,subtopico:`Contração muscular`,dificuldade:`facil`,enunciado:`Julgue o item sobre o mecanismo de relaxamento muscular:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O relaxamento muscular ocorre quando o retículo sarcoplasmático recaptura o Ca²⁺ ativamente via Ca²⁺-ATPase (SERCA), reduzindo a concentração de cálcio citoplasmático, deslocando a tropomiosina e impedindo a interação actina-miosina.`,explicacao:`O relaxamento muscular é ativo e depende da recaptura de Ca²⁺ pelo retículo sarcoplasmático através da bomba SERCA (Ca²⁺-ATPase do retículo sarcoplasmático). Quando [Ca²⁺] citoplasmático cai abaixo de ~10⁻⁷ M, o Ca²⁺ se dissocia da troponina C, a tropomiosina recobre os sítios de ligação da miosina na actina e as pontes cruzadas se desfazem, resultando no relaxamento. Esse processo consome ATP.`},{id:`fisio-048`,banca:`UNESP`,ano:2020,prova:`UNESP — Residência em Clínica de Pequenos Animais 2020`,tipo:`residencia`,topico:`cardiovascular`,subtopico:`Débito cardíaco`,dificuldade:`medio`,enunciado:`O débito cardíaco (DC) é determinado pelo produto do volume sistólico (VS) pela frequência cardíaca (FC). Sobre o débito cardíaco em cães, assinale a alternativa CORRETA:`,alternativas:[`O débito cardíaco de um cão em repouso é de aproximadamente 20 L/min para um animal de 30 kg.`,`O débito cardíaco é calculado pela equação: DC = VS × FC, onde VS é o volume de sangue ejetado por batimento cardíaco.`,`O débito cardíaco é determinado exclusivamente pela frequência cardíaca, sem influência do volume sistólico.`,`O débito cardíaco de cães em repouso é de aproximadamente 2-4 L/min para um animal de 30 kg, e aumenta significativamente durante o exercício.`,`O débito cardíaco não é influenciado pelo retorno venoso nem pela contratilidade miocárdica.`],resposta_correta:`B`,explicacao:`O débito cardíaco (DC) = Volume Sistólico (VS) × Frequência Cardíaca (FC). O VS é o volume de sangue ejetado por cada batimento (~40-60 mL em cães de 30 kg) e depende da pré-carga, pós-carga e contratilidade. O DC em repouso é ~2-4 L/min para cães de 30 kg (opção D também é correta na descrição, mas a B é mais precisa na definição). O DC pode aumentar 4-5x durante exercício intenso.`},{id:`fisio-049`,banca:`UFMT`,ano:2022,prova:`UFMT — Concurso Professor Fisiologia 2022`,tipo:`concurso`,topico:`cardiovascular`,subtopico:`Volume sistólico`,dificuldade:`dificil`,enunciado:`O volume sistólico é influenciado por três fatores principais. Sobre a Lei de Frank-Starling, assinale a alternativa CORRETA:`,alternativas:[`A Lei de Frank-Starling afirma que o coração ejeita menos sangue quando o enchimento diastólico (pré-carga) aumenta, como mecanismo de proteção contra sobrecarga.`,`A Lei de Frank-Starling afirma que o volume sistólico aumenta quando o retorno venoso (pré-carga) aumenta, pois o maior enchimento ventricular estira os miofibrilas, gerando maior força de contração.`,`A Lei de Frank-Starling aplica-se exclusivamente ao átrio direito e não ao ventrículo esquerdo.`,`A Lei de Frank-Starling é válida apenas durante o exercício físico, não se aplicando em repouso.`,`A Lei de Frank-Starling afirma que a frequência cardíaca determina exclusivamente o volume sistólico.`],resposta_correta:`B`,explicacao:`A Lei de Frank-Starling (Lei do coração) afirma que o volume ejetado pelo ventrículo (VS) é proporcional ao volume recebido (enchimento diastólico). Quando o retorno venoso aumenta → maior pré-carga → maior estiramento dos sarcômeros → maior força de contração (por otimização da interação actina-miosina e maior sensibilidade ao Ca²⁺) → maior VS. Isso permite que o coração se ajuste automaticamente às variações de retorno venoso.`},{id:`fisio-050`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`cardiovascular`,subtopico:`Eletrofisiologia cardíaca`,dificuldade:`medio`,enunciado:`O sistema de condução cardíaco gera e propaga o impulso elétrico. Sobre o marca-passo cardíaco, assinale a alternativa CORRETA:`,alternativas:[`O nó sinoatrial (SA) é o marca-passo primário do coração, com frequência de disparo espontâneo de aproximadamente 100 bpm em cães, podendo ser modificado pelo sistema nervoso autônomo.`,`O nó atrioventricular (AV) é o marca-passo primário, com frequência de disparo superior a 200 bpm.`,`O feixe de His conduz o impulso apenas dos ventrículos para os átrios, em sentido retrógrado.`,`O sistema de condução cardíaco não é influenciado pelo sistema nervoso autônomo.`,`As fibras de Purkinje conduzem o impulso apenas pelo septo interatrial, sem ramificação ventricular.`],resposta_correta:`A`,explicacao:`O nó SA é o marca-passo primário com frequência intrínseca de ~100 bpm em cães (60-140 bpm dependendo do tônus autônomo). Possui automaticidade (fase 4 espontânea — despolarização diastólica lenta por correntes de If e ICa-T). O parassimpático (vago) reduz a FC (bradicardia) e o simpático aumenta (taquicardia). O nó AV (opção B) é o marca-passo secundário (~40-60 bpm). As fibras de Purkinje (opção E) conduzem rapidamente pelos ventrículos.`},{id:`fisio-051`,banca:`CRMV`,ano:2022,prova:`CRMV — Exame de Qualificação 2022`,tipo:`crmv`,topico:`cardiovascular`,subtopico:`Circulação coronariana`,dificuldade:`medio`,enunciado:`A circulação coronariana irriga o miocárdio e é essencial para a função cardíaca. Sobre a circulação coronariana, assinale a alternativa CORRETA:`,alternativas:[`O fluxo coronariano ocorre predominantemente durante a sístole ventricular, quando a pressão intramiocárdica é máxima.`,`O fluxo coronariano no ventrículo esquerdo é predominantemente diastólico, pois durante a sístole a compressão intramiocárdica impede o fluxo nos vasos subendocárdicos.`,`A circulação coronariana não é regulada por fatores metabólicos locais, dependendo apenas do sistema nervoso autônomo.`,`O miocárdio extrai apenas 25% do oxigênio do sangue coronariano, possuindo grande reserva de extração.`,`A adenosina é um vasoconstritor coronariano que reduz o fluxo sanguíneo durante o exercício.`],resposta_correta:`B`,explicacao:`No ventrículo esquerdo, o fluxo coronariano é predominantemente DIASTÓLICO. Durante a sístole, a compressão dos vasos intramiocárdicos pelo miocárdio contraído (especialmente subendocárdio) impede o fluxo. Na diástole, com o relaxamento, o fluxo é máximo. O miocárdio (opção D) extrai ~70-80% do O₂ (máxima extração), tendo pouca reserva — o aumento da oferta depende do aumento do fluxo. A adenosina (opção E) é um potente vasodilatador coronariano produzido por cardiomiócitos hipóxicos.`},{id:`fisio-052`,banca:`ENAV`,ano:2023,prova:`ENAV — Concurso 2023`,tipo:`enav`,topico:`respiratorio`,subtopico:`Surfactante pulmonar`,dificuldade:`medio`,enunciado:`O surfactante pulmonar é essencial para a mecânica respiratória. Sobre o surfactante, assinale a alternativa CORRETA:`,alternativas:[`O surfactante pulmonar é produzido pelos pneumócitos tipo I e é composto principalmente por proteínas estruturais.`,`O surfactante reduz a tensão superficial nos alvéolos, prevenindo o colapso alveolar (atelectasia) e facilitando a expansão pulmonar.`,`O surfactante aumenta a tensão superficial alveolar para manter os alvéolos sempre fechados durante a expiração.`,`O surfactante é produzido exclusivamente após o nascimento, sendo ausente em fetos a termo.`,`A deficiência de surfactante causa enfisema pulmonar (hiperinsuflação), não atelectasia.`],resposta_correta:`B`,explicacao:`O surfactante é produzido pelos pneumócitos tipo II e composto principalmente por fosfolipídeos (~90%, principalmente dipalmitoilfosfatidilcolina — DPPC) e proteínas surfactantes (SP-A, SP-B, SP-C, SP-D). Reduz a tensão superficial, prevenindo colapso alveolar (Lei de Laplace: P = 2T/r). A deficiência (opção E) causa Síndrome do Desconforto Respiratório (SDR) — atelectasia difusa, comum em prematuros. O surfactante fetal é produzido a partir da 24ª semana de gestação (opção D).`},{id:`fisio-053`,banca:`CESPE`,ano:2020,prova:`CESPE — Analista MAPA 2020`,tipo:`concurso`,topico:`respiratorio`,subtopico:`Volumes pulmonares`,dificuldade:`facil`,enunciado:`Julgue o item sobre volumes e capacidades pulmonares:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A capacidade vital (CV) é o volume máximo de ar que pode ser expirado após uma inspiração máxima, sendo calculada pela soma do volume corrente, volume de reserva inspiratório e volume de reserva expiratório.`,explicacao:`A capacidade vital (CV) = VCI (volume corrente, ~15 mL/kg) + VRI (volume de reserva inspiratório, ~30 mL/kg) + VRE (volume de reserva expiratório, ~30 mL/kg) = ~75 mL/kg em cães. CV = Volume Inspiratório Capacidade + VRE, ou CV = Capacidade Pulmonar Total - Volume Residual. É um parâmetro clínico importante para avaliar a função pulmonar.`},{id:`fisio-054`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Concurso Municipal 2021`,tipo:`concurso`,topico:`respiratorio`,subtopico:`Quimiorreceptores`,dificuldade:`medio`,enunciado:`A respiração é regulada por quimiorreceptores centrais e periféricos. Sobre a regulação química da respiração, assinale a alternativa CORRETA:`,alternativas:[`Os quimiorreceptores centrais localizados no bulbo respondem exclusivamente à hipóxia (redução de O₂), sem sensibilidade ao CO₂.`,`Os quimiorreceptores periféricos no corpo carotídeo e aórtico respondem à hipóxia, hipercapnia e acidose, enviando aferências via nervos glossofaríngeo e vago.`,`A hipercapnia (aumento de CO₂) inibe o centro respiratório bulbar, causando apneia.`,`O CO₂ não atravessa a barreira hematoencefálica e por isso não influencia os quimiorreceptores centrais.`,`Os quimiorreceptores periféricos são os únicos responsáveis pela regulação da respiração em repouso.`],resposta_correta:`B`,explicacao:`Os quimiorreceptores periféricos estão nos corpos carotídeos (inervados pelo nervo glossofaríngeo — IX) e aórticos (inervados pelo vago — X). Respondem a: (1) hipóxia (↓pO₂), (2) hipercapnia (↑pCO₂) e (3) acidose (↓pH). Os quimiorreceptores centrais (opção A) no bulbo respondem principalmente ao ↑CO₂/H⁺ (CO₂ → H₂CO₃ → H⁺ + HCO₃⁻). O CO₂ (opção D) atravessa facilmente a barreira hematoencefálica.`},{id:`fisio-055`,banca:`UFRRJ`,ano:2020,prova:`UFRRJ — Residência em Clínica de Equinos 2020`,tipo:`residencia`,topico:`respiratorio`,subtopico:`Regulação da respiração`,dificuldade:`dificil`,enunciado:`A regulação da respiração envolve múltiplos centros no tronco encefálico. Sobre os centros respiratórios, assinale a alternativa CORRETA:`,alternativas:[`O centro pneumotáxico (ponte) prolonga a inspiração e reduz a frequência respiratória.`,`O centro apneústico (ponte) promove a inspiração prolongada; quando lesado, a inspiração torna-se curta e a expiração precoce.`,`O grupo respiratório ventral do bulbo controla apenas a expiração, sem papel na inspiração.`,`O centro respiratório bulbar dorsal é responsável exclusivamente pela expiração ativa.`,`A regulação respiratória não é influenciada por aferências proprioceptivas dos pulmões.`],resposta_correta:`B`,explicacao:`O centro apneústico na ponte promove inspiração prolongada (apneústico = "sem respiração" se lesado — inspirações curtas). O centro pneumotáxico (opção A) limita a inspiração e aumenta a frequência respiratória. O grupo ventral bulbar (opção C) controla inspiração E expiração forçada. O grupo dorsal bulbar (opção D) é o centro inspiratório principal. As aferências vagais (opção E) dos receptores de estiramento pulmonar (Hering-Breuer) limitam a inspiração.`},{id:`fisio-056`,banca:`UFBA`,ano:2023,prova:`UFBA — Residência em Clínica de Pequenos Animais 2023`,tipo:`residencia`,topico:`respiratorio`,subtopico:`Hemoglobina`,dificuldade:`medio`,enunciado:`A hemoglobina (Hb) é a principal proteína de transporte de oxigênio no sangue. Sobre a hemoglobina, assinale a alternativa CORRETA:`,alternativas:[`A hemoglobina é composta por quatro subunidades de globina, cada uma contendo um grupo heme com ferro no estado Fe³⁺ (férrico) para ligação do O₂.`,`A hemoglobina é composta por quatro subunidades de globina (2α e 2β em adultos), cada uma com um grupo heme contendo ferro no estado Fe²⁺ (ferroso), permitindo a ligação reversível com O₂.`,`A hemoglobina é uma proteína de cadeia simples com um único grupo heme, semelhante à mioglobina.`,`A hemoglobina liga-se irreversivelmente ao oxigênio, não podendo liberá-lo nos tecidos.`,`A carboxihemoglobina (HbCO) é a forma ativa da hemoglobina que transporta CO₂ dos tecidos para os pulmões.`],resposta_correta:`B`,explicacao:`A hemoglobana adulta (HbA) é um tetrâmero: 2 cadeias α + 2 cadeias β, cada uma com grupo heme (protoporfirina IX + Fe²⁺). O Fe²⁺ (ferroso) liga reversivelmente o O₂. Se oxidado para Fe³⁺ (férrico), forma metemoglobina (não transporta O₂). A Hb transporta O₂ (oxiemoglobina) E CO₂ (carbaminohemoglobina — opção E). A carboxihemoglobina (HbCO) é a ligação com CO (monóxido de carbono) — irreversível e tóxica.`},{id:`fisio-057`,banca:`USP`,ano:2021,prova:`USP — Residência em Clínica Cirúrgica Veterinária 2021`,tipo:`residencia`,topico:`respiratorio`,subtopico:`Efeito Bohr`,dificuldade:`dificil`,enunciado:`O efeito Bohr descreve a influência do pH e do CO₂ na afinidade da hemoglobina pelo O₂. Sobre o efeito Bohr e o efeito Haldane, assinale a alternativa CORRETA:`,alternativas:[`O efeito Bohr afirma que o aumento do pH (alcalose) aumenta a afinidade da Hb pelo O₂, facilitando a liberação de O₂ nos tecidos.`,`O efeito Bohr afirma que o aumento de CO₂ e H⁺ (acidose) diminui a afinidade da Hb pelo O₂, facilitando a liberação de O₂ nos tecidos metabolicamente ativos.`,`O efeito Haldane afirma que a desoxihemoglobina tem menor afinidade pelo CO₂ que a oxihemoglobina.`,`O efeito Bohr atua apenas nos pulmões, facilitando a captação de O₂.`,`Os efeitos Bohr e Haldane são mutuamente exclusivos e não ocorrem simultaneamente no organismo.`],resposta_correta:`B`,explicacao:`O efeito Bohr: ↑CO₂, ↑H⁺ (↓pH/acidose) e ↑temperatura → ↓afinidade da Hb pelo O₂ → facilita liberação de O₂ nos tecidos ativos (músculo em exercício). Tecidos ativos produzem CO₂ e H⁺, que desviam a curva para a direita localmente. O efeito Haldane (opção C): a desoxihemoglobina tem MAIOR afinidade pelo CO₂ (carbamino). Os dois efeitos ocorrem simultaneamente (opção E). O efeito Bohr (opção D) atua nos TECIDOS (liberação O₂), não nos pulmões.`},{id:`fisio-058`,banca:`ENAV`,ano:2017,prova:`ENAV — Concurso 2017`,tipo:`enav`,topico:`respiratorio`,subtopico:`Mioglobina`,dificuldade:`facil`,enunciado:`A mioglobina é uma proteína de armazenamento de oxigênio no músculo. Sobre a mioglobina, assinale a alternativa CORRETA:`,alternativas:[`A mioglobina é uma proteína tetramérica, semelhante à hemoglobina, com quatro grupos heme.`,`A mioglobina possui alta afinidade pelo O₂ em baixas pressões parciais, servindo como reserva de oxigênio no músculo e facilitando a transferência de O₂ da hemoglobina para as mitocôndrias.`,`A mioglobina liga-se ao CO₂ para transportá-lo dos tecidos para os pulmões.`,`A mioglobina é encontrada exclusivamente no sangue, não existindo no tecido muscular.`,`A mioglobina apresenta curva de dissociação sigmoide, semelhante à hemoglobina, com cooperatividade.`],resposta_correta:`B`,explicacao:`A mioglobina é uma proteína MONOMÉRICA (opção A) com um único grupo heme. Possui afinidade muito maior pelo O₂ que a hemoglobina (curva hiperbólica — sem cooperatividade — opção E). A alta afinidade em baixas pO₂ permite: (1) armazenar O₂ no músculo, (2) facilitar a transferência de O₂ da Hb (pO₂ ~30 mmHg nos capilares) para as mitocôndrias (pO₂ ~1-5 mmHg). Músculos com alta atividade oxidativa são ricos em mioglobina ("músculo vermelho").`},{id:`fisio-059`,banca:`UFPE`,ano:2020,prova:`UFPE — Residência em Clínica de Grandes Animais 2020`,tipo:`residencia`,topico:`respiratorio`,subtopico:`Curva de dissociação da hemoglobina`,dificuldade:`medio`,enunciado:`A curva de dissociação da hemoglobina descreve a relação entre a pressão parcial de O₂ (pO₂) e a saturação da hemoglobina (SatHb). Sobre essa curva, assinale a alternativa CORRETA:`,alternativas:[`A curva de dissociação da hemoglobina é linear, indicando que a afinidade pelo O₂ é constante em todas as pressões parciais.`,`A curva de dissociação é sigmoide (forma de S) devido à cooperatividade entre as subunidades da hemoglobina, facilitando a captação de O₂ nos pulmões e a liberação nos tecidos.`,`A P50 (pO₂ à qual 50% da Hb está saturada) é de aproximadamente 80 mmHg em condições normais.`,`A curva desloca-se para a esquerda com o aumento da temperatura e do 2,3-DPG, facilitando a liberação de O₂.`,`Animais de grande altitude possuem curva deslocada para a esquerda como adaptação à hipóxia.`],resposta_correta:`B`,explicacao:`A curva sigmoide resulta da cooperatividade: quando o primeiro O₂ se liga à Hb, muda a conformação (T→R) facilitando a ligação dos O₂ seguintes. Isso permite: nos pulmões (pO₂ ~100 mmHg — platô superior — quase 100% saturação) e nos tecidos (pO₂ ~40 mmHal — porção descendente — liberação eficiente). A P50 (opção C) é ~26-27 mmHg. Desvio à esquerda (opção D) = ↑afinidade (↓P50). Animais de altitude (opção E) têm curva desviada à direita (↑2,3-DPG).`},{id:`fisio-060`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`renal`,subtopico:`Ducto coletor`,dificuldade:`medio`,enunciado:`O ducto coletor é o segmento final do néfron e realiza o ajuste final da urina. Sobre a ação do ADH (vasopressina) no ducto coletor, assinale a alternativa CORRETA:`,alternativas:[`O ADH atua nos receptores V2 das células principais do ducto coletor, ativando a via AMPc que promove a inserção de aquaporina-2 na membrana apical, permitindo a reabsorção de água.`,`O ADH atua nos receptores V1 do ducto coletor, promovendo a reabsorção de sódio e secreção de potássio.`,`O ADH inibe a reabsorção de água no ducto coletor, produzindo urina diluída.`,`O ADH atua exclusivamente nos túbulos proximais, não tendo efeito no ducto coletor.`,`O ADH é produzido pelo hipotálamo e armazenado no hipotálamo, sem liberação pela hipófise posterior.`],resposta_correta:`A`,explicacao:`O ADH (vasopressina) é produzido no hipotálamo (núcleos supraóptico e paraventricular) e armazenado/liberado pela neuro-hipófise (hipófise posterior). Atua nos receptores V2 das células principais do ducto coletor → ativação de proteína Gs → AMPc → PKA → fusão de vesículas contendo AQP2 na membrana apical. Isso torna o ducto permeável à água, que é reabsorvida por osmose. Na ausência de ADH (diabetes insipidus), a urina é diluída.`},{id:`fisio-061`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário MAPA 2022`,tipo:`concurso`,topico:`renal`,subtopico:`Clearance renal`,dificuldade:`dificil`,enunciado:`Julgue o item sobre clearance renal:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O clearance de creatinina é utilizado clinicamente como estimativa da taxa de filtração glomerular (TFG), pois a creatinina é livremente filtrada no glomérulo e possui mínima reabsorção tubular, embora haja pequena secreção tubular que pode superestimar ligeiramente a TFG.`,explicacao:`A creatinina é um produto do metabolismo da creatina muscular. É livremente filtrada no glomérulo, praticamente não reabsorvida nos túbulos, mas apresenta pequena secreção tubular (~10-15%), o que pode superestimar ligeiramente a TFG. Apesar disso, é o método clínico mais prático para estimar a TFG (mais conveniente que inulina, que é o método de referência). Em cães, o clearance de creatinina normal é ~3-5 mL/kg/min.`},{id:`fisio-062`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Veterinário Prefeitura 2023`,tipo:`concurso`,topico:`renal`,subtopico:`Regulação de sódio e potássio`,dificuldade:`medio`,enunciado:`O rim regula o equilíbrio de sódio e potássio no organismo. Sobre a regulação de Na⁺ e K⁺ no néfron, assinale a alternativa CORRETA:`,alternativas:[`Aproximadamente 90% do sódio filtrado é reabsorvido no túbulo proximal, por mecanismos ativos (Na⁺/K⁺-ATPase na membrana basolateral) e co-transporte.`,`A aldosterona atua no túbulo proximal, aumentando a reabsorção de sódio e a secreção de potássio.`,`O potássio é exclusivamente reabsorvido no rim, sem secreção em nenhum segmento do néfron.`,`A regulação de sódio é exclusivamente tubuloglomerular, sem envolvimento hormonal.`,`O túbulo distal não participa da regulação de potássio, sendo responsabilidade exclusiva do ducto coletor.`],resposta_correta:`A`,explicacao:`O túbulo proximal reabsorve ~65-70% do Na⁺ filtrado (transporte ativo pela Na⁺/K⁺-ATPase basolateral + co-transporte Na⁺-glicose, Na⁺-aminoácidos, Na⁺/H⁺ antiporte). A aldosterona (opção B) atua nas células principais do DUCTO COLETOR (e túbulo distal), aumentando reabsorção de Na⁺ e secreção de K⁺. O K⁺ (opção C) é reabsorvido no túbulo proximal e alça de Henle, e SECRETADO no ducto coletor (regulado por aldosterona).`},{id:`fisio-063`,banca:`UFMG`,ano:2022,prova:`UFMG — Concurso Professor Adjunto 2022`,tipo:`concurso`,topico:`renal`,subtopico:`Sistema renina-angiotensina-aldosterona`,dificuldade:`dificil`,enunciado:`O sistema renina-angiotensina-aldosterona (SRAA) é fundamental para a regulação da pressão arterial e do equilíbrio hidroeletrolítico. Sobre o SRAA, assinale a alternativa CORRETA:`,alternativas:[`A renina é produzida pelas células do túbulo coletor em resposta à hipernatremia.`,`A renina é produzida pelas células justaglomerulares (JG) do aferente em resposta à hipotensão, hipovolemia ou redução de Na⁺ no filtrado, e converte angiotensinogênio em angiotensina I.`,`A angiotensina II é um potente vasodilatador que reduz a pressão arterial.`,`A aldosterona é produzida pela medula da adrenal e atua nos túbulos proximais.`,`O SRAA é inibido pela elevação da pressão arterial e pelo aumento do Na⁺ plasmático.`],resposta_correta:`B`,explicacao:`As células JG (músculo liso do arteríolo aferente) produzem renina em resposta a: (1) ↓pressão no aferente (barorreceptor), (2) ↓Na⁺ no filtrado (mácula densa), (3) estimulação simpática (β1). Renina converte angiotensinogênio (fígado) → Ang I. ECA (pulmões) converte Ang I → Ang II. Ang II: vasoconstritor potente, estimula aldosterona (córtez adrenal — opção D), ADH, sede, reabsorção de Na⁺. Aldosterona atua no ducto coletor.`},{id:`fisio-064`,banca:`ENAV`,ano:2018,prova:`ENAV — Concurso 2018`,tipo:`enav`,topico:`renal`,subtopico:`Alça de Henle`,dificuldade:`medio`,enunciado:`A alça de Henle é essencial para o mecanismo de contracorrente e a concentração urinária. Sobre a alça de Henle, assinale a alternativa CORRETA:`,alternativas:[`A porção descendente fina é impermeável à água e permeável a NaCl, diluindo o fluido tubular.`,`A porção ascendente espessa transporta ativamente Na⁺, K⁺ e 2Cl⁻ (cotransporter NKCC2) e é impermeável à água, sendo o principal sítio de geração do gradiente osmótico medular.`,`A porção ascendente fina é permeável à água, permitindo a reabsorção passiva de água no interstício hipertônico.`,`A alça de Henle reabsorve 100% da glicose filtrada, semelhante ao túbulo proximal.`,`O diurético de alça furosemida atua na porção descendente da alça de Henle, inibindo a reabsorção de água.`],resposta_correta:`B`,explicacao:`A porção ascendente espessa da alça de Henle contém o cotransporter NKCC2 (Na⁺/K⁺/2Cl⁻) na membrana apical, que transporta ativamente esses íons para o interstício medular. Como é impermeável à água, dilui o fluido tubular e concentra o interstício, gerando o gradiente osmótico (até ~1200 mOsm/L na papila renal). A furosemida (opção E) inibe o NKCC2 na porção ASCENDENTE espessa. A porção descendente (opção A) é permeável à água e impermeável a solutos.`},{id:`fisio-065`,banca:`UNESP`,ano:2019,prova:`UNESP — Residência em Clínica de Pequenos Animais 2019`,tipo:`residencia`,topico:`digestorio`,subtopico:`Salivação`,dificuldade:`facil`,enunciado:`A saliva é produzida pelas glândulas salivares e possui múltiplas funções. Sobre a saliva em cães, assinale a alternativa CORRETA:`,alternativas:[`A saliva é produzida exclusivamente pelas glândulas parótidas, não havendo outras glândulas salivares em cães.`,`A saliva contém amilase salivar (ptialina) que inicia a digestão do amido, e possui pH levemente alcalino (7,0-8,0) que favorece a ação enzimática.`,`A saliva é produzida apenas durante a alimentação, não havendo produção basal em repouso.`,`A saliva canina contém lipase salivar em alta concentração, responsável pela digestão de gorduras no estômago.`,`A saliva não possui função antibacteriana, sendo apenas um lubrificante para a deglutição.`],resposta_correta:`B`,explicacao:`A saliva canina é produzida pelas glândulas parótidas, mandibulares, sublinguais e zigomáticas (opção A). Contém amilase salivar (ptialina) que inicia a digestão do amido (embora tenha ação limitada pelo tempo de permanência na boca). O pH alcalino (7,0-8,0) tampona os ácidos e protege o esmalte dentário. A produção basal (opção C) é contínua (~1-2 L/dia em cães). A saliva possui lisozima e IgA (opção E) com função antibacteriana.`},{id:`fisio-066`,banca:`FCC`,ano:2021,prova:`FCC — Veterinário IBAMA 2021`,tipo:`concurso`,topico:`digestorio`,subtopico:`Deglutição`,dificuldade:`medio`,enunciado:`A deglutição é um ato motor complexo que envolve fases orais, faríngeas e esofágicas. Sobre a deglutição, assinale a alternativa CORRETA:`,alternativas:[`A fase oral da deglutição é involuntária e controlada pelo centro da deglutição no bulbo.`,`A fase faríngea da deglutição é involuntária (reflexa) e envolve o fechamento da glote, elevação da laringe e abertura do esfíncter esofágico superior.`,`A fase esofágica é voluntária e controlada conscientemente pelo animal.`,`O peristaltismo esofágico ocorre apenas por mecanismo miogênico, sem participação neural.`,`A deglutição não é influenciada pelo sistema nervoso autônomo.`],resposta_correta:`B`,explicacao:`A fase faríngea é um reflexo automático (involuntário) coordenado pelo centro da deglutição bulbar (núcleo do trato solitário). Inclui: (1) elevação do palato mole (previne refluxo nasal), (2) elevação da laringe e fechamento da glote (protege vias aéreas), (3) contração faríngea, (4) relaxamento do esfíncter esofágico superior. A fase oral (opção A) é VOLUNTÁRIA. A fase esofágica (opção C) é involuntária (peristaltismo primário e secundário).`},{id:`fisio-067`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Prova de Título em Clínica de Pequenos Animais 2022`,tipo:`concurso`,topico:`digestorio`,subtopico:`Motilidade intestinal`,dificuldade:`medio`,enunciado:`A motilidade gastrointestinal é regulada pelo sistema nervoso entérico e hormônios gastrointestinais. Sobre os movimentos intestinais, assinale a alternativa CORRETA:`,alternativas:[`O reflexo gastrocólico é uma onda peristáltica que ocorre no estômago após a ingestão de alimento, sem efeito sobre o intestino grosso.`,`O complexo mioelétrico migrante (CMM) é o padrão de motilidade que ocorre em jejum, limpando o estômago e intestino delgado de resíduos a cada 90-120 minutos.`,`As contrações de segmentação no intestino grosso são responsáveis pelo transporte rápido do quimo em direção ao reto.`,`A motilidade intestinal é controlada exclusivamente pelo sistema nervoso central, sem participação do sistema nervoso entérico.`,`O peristaltismo é inibido pela acetilcolina liberada pelo sistema nervoso parassimpático.`],resposta_correta:`B`,explicacao:`O complexo mioelétrico migrante (CMM) é um padrão cíclico de motilidade que ocorre durante o jejum interdigestivo, a cada 90-120 min (cão). Origina-se no estômago e migra pelo intestino delgado, limpando de resíduos, bactérias e secreções. É regulado pela motilina. O reflexo gastrocólico (opção A) ocorre após a refeição e estimula a motilidade do CÓLON. O peristaltismo (opção E) é ESTIMULADO pela ACh (parassimpático).`},{id:`fisio-068`,banca:`ENAV`,ano:2020,prova:`ENAV — Concurso 2020`,tipo:`enav`,topico:`digestorio`,subtopico:`Absorção de nutrientes`,dificuldade:`medio`,enunciado:`A absorção de nutrientes ocorre principalmente no intestino delgado. Sobre os mecanismos de absorção, assinale a alternativa CORRETA:`,alternativas:[`A glicose é absorvida no intestino delgado por difusão simples, sem necessidade de transportadores.`,`A glicose e a galactose são absorvidas por co-transporte Na⁺-glicose (SGLT1) na membrana apical dos enterócitos, e saem pela membrana basolateral via GLUT2.`,`Os aminoácidos são absorvidos exclusivamente por endocitose, sem envolvimento de transportadores de membrana.`,`Os lipídeos são absorvidos na forma de quilomícrons inteiros, sem necessidade de digestão prévia.`,`A absorção de água no intestino delgado é ativa e depende de ATP diretamente.`],resposta_correta:`B`,explicacao:`A glicose e galactose entram no enterócito pelo co-transportador SGLT1 (Na⁺-glicose) na membrana apical, usando o gradiente de Na⁺ mantido pela Na⁺/K⁺-ATPase basolateral. Saem pela membrana basolateral via GLUT2 (difusão facilitada). A frutose entra via GLUT5 (difusão facilitada). Aminoácidos (opção C) são absorvidos por transportadores específicos. Lipídeos (opção D) são absorvidos como ácidos graxos e monoglicerídeos, re-esterificados e exportados como quilomícrons.`},{id:`fisio-069`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`endocrino`,subtopico:`Hipófise`,dificuldade:`medio`,enunciado:`A hipófise (pituitária) é uma glândula endócrina central que regula diversas outras glândulas. Sobre os hormônios hipofisários, assinale a alternativa CORRETA:`,alternativas:[`A adeno-hipófise (hipófise anterior) produz hormônios como GH, TSH, ACTH, LH, FSH e prolactina, que são regulados por hormônios hipotalâmicos via sistema portal hipotálamo-hipofisário.`,`A neuro-hipófise (hipófise posterior) produz ADH e ocitocina diretamente em seus axônios.`,`A hipófise intermediária é a maior porção da hipófise em cães e produz a maioria dos hormônios hipofisários.`,`O GH (hormônio do crescimento) é regulado positivamente pelo GHRH e negativamente pela somatostatina, mas não há feedback negativo do GH sobre o hipotálamo.`,`A adeno-hipófise produz apenas hormônios trópicos, sem efeito direto sobre tecidos periféricos.`],resposta_correta:`A`,explicacao:`A adeno-hipófise produz hormônios regulados por hormônios liberadores e inibidores hipotalâmicos via sistema portal hipotálamo-hipofisário: GHRH/somatostatina → GH; TRH → TSH; CRH → ACTH; GnRH → LH/FSH; dopamina (inibe) → prolactina. A neuro-hipófise (opção B) ARMAZENA e LIBERA ADH e ocitocina (produzidas no hipotálamo). O GH (opção D) tem feedback negativo (IGF-1 hepático inibe GH e estimula somatostatina).`},{id:`fisio-070`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Veterinário Concurso Estadual 2022`,tipo:`concurso`,topico:`endocrino`,subtopico:`Paratireoide`,dificuldade:`medio`,enunciado:`As glândulas paratireoides regulam o metabolismo do cálcio e do fósforo. Sobre o paratormônio (PTH), assinale a alternativa CORRETA:`,alternativas:[`O PTH é secretado em resposta à hipercalcemia e promove a redução dos níveis de cálcio plasmático.`,`O PTH é secretado pelas células oxífilas das paratireoides em resposta à hipocalcemia e promove: reabsorção óssea (liberação de Ca²⁺), reabsorção renal de Ca²⁺ e ativação da vitamina D.`,`O PTH atua exclusivamente no osso, sem efeito renal ou intestinal.`,`A calcitonina e o PTH têm o mesmo efeito sobre o cálcio plasmático, ambos aumentando os níveis de Ca²⁺.`,`O PTH inibe a reabsorção óssea e estimula a deposição de cálcio nos ossos.`],resposta_correta:`B`,explicacao:`O PTH é produzido pelas células principais (não oxífilas) das paratireoides em resposta à ↓Ca²⁺ plasmático (detectado por receptores CaSR). Efeitos do PTH: (1) osso — ativa osteoclastos (via RANKL), reabsorção óssea, libera Ca²⁺ e PO₄³⁻; (2) rim — ↑reabsorção de Ca²⁺ no DCT, ↓reabsorção de PO₄³⁻, ativa 1α-hidroxilase (vitamina D ativa); (3) intestino — indiretamente, via vitamina D, ↑absorção de Ca²⁺. A calcitonina (opção D) é antagônica ao PTH (↓Ca²⁺).`},{id:`fisio-071`,banca:`UFMT`,ano:2023,prova:`UFMT — Residência em Clínica de Ruminantes 2023`,tipo:`residencia`,topico:`endocrino`,subtopico:`Adrenal`,dificuldade:`dificil`,enunciado:`As glândulas adrenais produzem hormônios essenciais para a homeostase. Sobre os hormônios adrenais, assinale a alternativa CORRETA:`,alternativas:[`O córtex adrenal produz catecolaminas (adrenalina e noradrenalina) e a medula produz glicocorticoides e mineralocorticoides.`,`O córtex adrenal é dividido em zonas glomerulosa (mineralocorticoides — aldosterona), fasciculada (glicocorticoides — cortisol) e reticular (andrógenos — DHEA).`,`O cortisol é o principal mineralocorticoide, responsável pela reabsorção de sódio nos túbulos renais.`,`A aldosterona é regulada exclusivamente pelo ACTH, sem influência do SRAA ou do potássio plasmático.`,`A medula adrenal produz exclusivamente noradrenalina, sem síntese de adrenalina.`],resposta_correta:`B`,explicacao:`O córtex adrenal tem três zonas: (1) Glomerulosa — aldosterona (mineralocorticoide, regulada pelo SRAA e K⁺); (2) Fasciculada — cortisol (glicocorticoide, regulada pelo ACTH); (3) Reticular — DHEA/androstenediona (andrógenos). A medula (opção A) produz catecolaminas (~80% adrenalina, ~20% noradrenalina). A aldosterona (opção C) é o principal mineralocorticoide. O cortisol (opção C) é glicocorticoide, com leve atividade mineralocorticoide.`},{id:`fisio-072`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`endocrino`,subtopico:`Hormônio do crescimento`,dificuldade:`medio`,enunciado:`O hormônio do crescimento (GH/somatotrofina) possui múltiplas ações metabólicas. Sobre o GH, assinale a alternativa CORRETA:`,alternativas:[`O GH é produzido pelas células tireotróficas da adeno-hipófise e é regulado pelo TRH.`,`O GH estimula o crescimento linear ósseo e a síntese proteica, mas também possui efeitos diabetogênicos (resistência insulínica) e lipolíticos.`,`O GH atua diretamente nos tecidos periféricos, sem necessidade de mediadores como o IGF-1.`,`O GH é secretado de forma constante ao longo do dia, sem padrão pulsátil.`,`O GH tem efeito exclusivamente anabólico, não possuindo ações catabólicas sobre o metabolismo de carboidratos.`],resposta_correta:`B`,explicacao:`O GH é produzido pelas células somatotróficas (não tireotróficas — opção A) da adeno-hipófise. Efeitos: (1) crescimento — estimula a produção hepática de IGF-1, que promove crescimento ósseo e síntese proteica; (2) metabólicos — lipólise (↑ácidos graxos), resistência insulínica (efeito diabetogênico), ↑gliconeogênese. O GH (opção C) atua diretamente em alguns tecidos E indiretamente via IGF-1. É secretado em pulsos (opção D), principalmente durante o sono profundo.`},{id:`fisio-073`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência em Reprodução Animal 2023`,tipo:`residencia`,topico:`reprodutivo`,subtopico:`Espermatogênese`,dificuldade:`medio`,enunciado:`A espermatogênese é o processo de produção de espermatozoides nos túbulos seminíferos. Sobre a espermatogênese, assinale a alternativa CORRETA:`,alternativas:[`A espermatogênese ocorre no interstício do testículo, sob controle exclusivo da testosterona.`,`A espermatogênese ocorre nos túbulos seminíferos e envolve mitose (espermatogônias → espermatócitos primários), meiose (espermatócitos → espermátides) e diferenciação (espermiogênese → espermatozoides maduros).`,`A espermatogênese é regulada exclusivamente pelo FSH, sem envolvimento do LH ou testosterona.`,`A espermiogênese é a fase de divisão celular que produz quatro espermátides a partir de um espermatócito primário.`,`Os espermatozoides são produzidos e liberados já com capacidade de motilidade e fertilização no testículo.`],resposta_correta:`B`,explicacao:`A espermatogênese nos túbulos seminíferos: (1) Mitose — espermatogônias (2n) → espermatócitos primários (2n); (2) Meiose I — espermatócitos primários → espermatócitos secundários (n); (3) Meiose II → espermátides (n); (4) Espermiogênese — diferenciação das espermátides em espermatozoides maduros (sem divisão). FSH (células de Sertoli) e LH (células de Leydig → testosterona) regulam o processo. Espermatozoides (opção E) ganham maturação no epidídimo.`},{id:`fisio-074`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`reprodutivo`,subtopico:`Ciclo estral bovino`,dificuldade:`medio`,enunciado:`Sobre o ciclo estral de vacas, assinale a alternativa CORRETA:`,alternativas:[`As vacas são poliéstricas sazonais, com ciclos apenas durante o outono.`,`O ciclo estral bovino dura em média 21 dias, com estro de 12-18 horas. A ovulação ocorre 24-30 horas após o início do estro.`,`As vacas ovulam múltiplos ovócitos, sendo comum a gestação gemelar.`,`O corpo lúteo bovino é mantido por toda a gestação, sem necessidade de progesterona placentária.`,`O proestro em vacas dura 1-2 dias, sendo o período mais curto do ciclo.`],resposta_correta:`B`,explicacao:`O ciclo estral bovino dura ~21 dias (18-24 dias). O estro (cio) é curto: 12-18 horas (o mais curto entre as espécies domésticas). A ovulação ocorre 24-30h após o INÍCIO do estro (após o fim do estro). Vacas (opção A) são poliéstricas NÃO-sazonais (o ano todo). Vacas (opção C) geralmente ovulam apenas 1 ovócito (gestação gemelar é rara, ~1%). O CL bovino (opção D) é mantido pelo eCG equino em caso de gestação, mas vacas produzem progesterona placentária.`},{id:`fisio-075`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame de Qualificação 2023`,tipo:`crmv`,topico:`reprodutivo`,subtopico:`Hormônios reprodutivos`,dificuldade:`facil`,enunciado:`Sobre os hormônios reprodutivos e seus efeitos, assinale a alternativa CORRETA:`,alternativas:[`O GnRH (hormônio liberador de gonadotrofinas) é produzido pela hipófise anterior e estimula a produção de LH e FSH.`,`O FSH (hormônio folículo-estimulante) atua nas células da granulosa do ovário, estimulando a foliculogênese e a produção de estrógenos.`,`O LH (hormônio luteinizante) atua exclusivamente nas células de Leydig do macho, sem efeito na fêmea.`,`A progesterona é produzida pelas células da granulosa antes da ovulação e mantém o endométrio para a implantação.`,`O estrógeno é produzido exclusivamente pelo corpo lúteo, sem participação dos folículos ovarianos.`],resposta_correta:`B`,explicacao:`O FSH atua nas células da granulosa dos folículos ovarianos, estimulando: (1) crescimento folicular, (2) aromatização de andrógenos em estrógenos (via aromatase), (3) expressão de receptores de LH. O GnRH (opção A) é produzido pelo HIPOTÁLAMO. O LH (opção C) atua na ovulação (pico de LH), luteinização (formação do CL) e nas células de Leydig (macho). A progesterona (opção D) é produzida pelo corpo lúteo PÓS-ovulação.`},{id:`fisio-076`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Veterinário Concurso Municipal 2021`,tipo:`concurso`,topico:`reprodutivo`,subtopico:`Ciclo estral equino`,dificuldade:`medio`,enunciado:`Sobre o ciclo estral de éguas, assinale a alternativa CORRETA:`,alternativas:[`As éguas são poliéstricas não-sazonais, com ciclos regulares durante todo o ano.`,`As éguas são poliéstricas sazonais (primavera-verão), com ciclos de ~21 dias e estro de 5-7 dias. A ovulação ocorre 24-48 horas antes do final do estro.`,`As éguas ovulam múltiplos ovócitos em cada ciclo, sendo a gestação gemelar muito comum.`,`O folículo ovariano em éguas ovula com diâmetro de 10-15 mm, semelhante ao de cadelas.`,`As éguas não possuem corpo lúteo após a ovulação, mantendo a progesterona exclusivamente por fontes adrenais.`],resposta_correta:`B`,explicacao:`As éguas são poliéstricas sazonais (ciclos durante primavera-verão, com anestro no inverno). Ciclo ~21 dias, estro 5-7 dias (o mais longo entre domésticos). Ovulação ocorre 24-48h antes do FIM do estro. O folículo ovula com ~40-50 mm (opção D). Geralmente ovulam 1 ovócito. O corpo lúteo (opção E) se forma e produz progesterona; se não há gestação, lisa em ~14-15 dias (luteólise por PGF2α).`},{id:`fisio-077`,banca:`ENAV`,ano:2024,prova:`ENAV — Concurso 2024`,tipo:`enav`,topico:`imunológico`,subtopico:`Imunidade celular`,dificuldade:`medio`,enunciado:`A imunidade celular é mediada principalmente por linfócitos T. Sobre os subtipos de linfócitos T, assinale a alternativa CORRETA:`,alternativas:[`Os linfócitos T CD4⁺ (helper) reconhecem antígenos apresentados por MHC classe I em qualquer célula do organismo.`,`Os linfócitos T CD8⁺ (citotóxicos) reconhecem antígenos apresentados por MHC classe II em células apresentadoras de antígenos e induzem apoptose nas células-alvo.`,`Os linfócitos T CD4⁺ (helper) reconhecem antígenos apresentados por MHC classe II em células apresentadoras de antígenos (APCs) e auxiliam na ativação de linfócitos B, macrófagos e outros linfócitos T.`,`Os linfócitos T CD4⁺ e CD8⁺ reconhecem antígenos livres no plasma, sem necessidade de apresentação por MHC.`,`Os linfócitos T reguladores (Treg) amplificam a resposta imune e causam autoimunidade.`],resposta_correta:`C`,explicacao:`Os linfócitos T CD4⁺ (helper) reconhecem antígenos processados e apresentados por MHC-II em APCs (células dendríticas, macrófagos, linfócitos B). Auxiliam: Th1 (imunidade celular), Th2 (humoral), Th17 (inflamação). Os T CD8⁺ (opção B) reconhecem MHC-I (células infectadas/tumorais) e induzem apoptose. Os T CD4⁺ reconhecem MHC-II (não MHC-I). Os Treg (opção E) SUPRIMEM respostas imunes excessivas.`},{id:`fisio-078`,banca:`UFBA`,ano:2020,prova:`UFBA — Concurso Professor Fisiologia 2020`,tipo:`concurso`,topico:`imunológico`,subtopico:`Imunidade humoral`,dificuldade:`medio`,enunciado:`A imunidade humoral é mediada por anticorpos (imunoglobulinas) produzidos por linfócitos B diferenciados em plasmócitos. Sobre as classes de imunoglobulinas, assinale a alternativa CORRETA:`,alternativas:[`A IgG é a imunoglobulina mais abundante no soro, atravessa a placenta (imunidade passiva neonatal) e tem a mais longa meia-vida entre as imunoglobulinas.`,`A IgM é secretada exclusivamente nas mucosas e não possui atividade de complemento.`,`A IgE está envolvida na defesa contra bactérias intracelulares e não participa de reações alérgicas.`,`A IgA é a principal imunoglobulina da resposta secundária, com alta afinidade e troca de classe.`,`A IgD é a imunoglobulina mais abundante no sangue e participa da fagocitose.`],resposta_correta:`A`,explicacao:`A IgG (~75% das Igs séricas) é a mais abundante, com meia-vida longa (~23 dias), atravessa a placenta (proteção neonatal), ativa complemento via via clássica e tem alta afinidade. IgM (opção B) é o primeiro anticorpo na resposta primária, pentamérico, ativa complemento eficientemente. IgE (opção C) media reações alérgicas (mastócitos) e defesa anti-helmíntica. IgA (opção D) é secretada em mucosas (leite, saliva, muco).`},{id:`fisio-079`,banca:`CESPE`,ano:2022,prova:`CESPE — Analista MAPA 2022`,tipo:`concurso`,topico:`imunológico`,subtopico:`Sistema complemento`,dificuldade:`dificil`,enunciado:`Julgue o item sobre o sistema complemento:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`O sistema complemento é composto por mais de 30 proteínas séricas que podem ser ativadas por três vias (clássica, alternativa e da lectina), resultando na formação do complexo de ataque à membrana (MAC — C5b-C9), lise osmótica de microrganismos, opsonização (C3b) e recrutamento de células inflamatórias (C3a, C5a — anafilatoxinas).`,explicacao:`O sistema complemento é uma cascata proteica da imunidade inata/auxiliar da adaptativa. Três vias de ativação: (1) Clássica — Ag-Ab (IgG/IgM) + C1q; (2) Alternativa — superfícies microbianas (spontânea, C3 tickover); (3) Lectina — lectina ligante de manose (MBL). Todas convergem em C3 → C3a/C3b → C5 → C5a/C5b → MAC (C5b-C9). Efeitos: lise, opsonização (C3b), inflamação (C3a/C5a — anafilatoxinas, quimiotaxia).`},{id:`fisio-080`,banca:`UNESP`,ano:2021,prova:`UNESP — Residência em Clínica de Pequenos Animais 2021`,tipo:`residencia`,topico:`imunológico`,subtopico:`Citocinas`,dificuldade:`medio`,enunciado:`As citocinas são proteínas sinalizadoras da resposta imune. Sobre as principais citocinas, assinale a alternativa CORRETA:`,alternativas:[`A IL-1, IL-6 e TNF-α são citocinas anti-inflamatórias que inibem a cascata inflamatória.`,`A IL-1, IL-6 e TNF-α são citocinas pró-inflamatórias produzidas principalmente por macrófagos ativados, que medeiam febre, recrutamento de leucócitos e resposta de fase aguda hepática.`,`A IL-2 é produzida por macrófagos e atua exclusivamente na diferenciação de neutrófilos.`,`A IL-10 é uma citocina pró-inflamatória que amplifica a resposta imune durante infecções bacterianas.`,`A IL-4 e IL-5 são citocinas que estimulam a diferenciação de linfócitos T CD8⁺ citotóxicos.`],resposta_correta:`B`,explicacao:`IL-1, IL-6 e TNF-α são as principais citocinas pró-inflamatórias, produzidas por macrófagos/monócitos. Efeitos: (1) TNF-α — ativação endotelial, recrutamento leucócito, choque séptico em excesso; (2) IL-1 — febre, ativação endotelial; (3) IL-6 — resposta de fase aguda (proteínas hepáticas como PCR), diferenciação de linfócitos B. IL-10 (opção D) é ANTI-inflamatória. IL-2 (opção C) é produzida por linfócitos T e estimula proliferação de T. IL-4/5 (opção E) estimulam diferenciação de B e eosinófilos.`},{id:`fisio-081`,banca:`ENAV`,ano:2017,prova:`ENAV — Concurso 2017`,tipo:`enav`,topico:`imunológico`,subtopico:`Inflamação`,dificuldade:`facil`,enunciado:`A resposta inflamatória aguda é uma defesa inata contra lesão e infecção. Sobre os sinais cardinais da inflamação, assinale a alternativa que apresenta os sinais clássicos:`,alternativas:[`Palidez, resfriamento, anestesia, diminuição de volume.`,`Rubor, calor, tumor, dor e perda de função.`,`Cianose, hipotermia, desidratação, taquicardia.`,`Icterícia, anemia, edema, prurido.`,`Necrose, fibrose, granuloma, cicatrização.`],resposta_correta:`B`,explicacao:`Os cinco sinais cardinais da inflamação (descritos por Celsus e Virchow): (1) Rubor (vermelhidão — vasodilatação), (2) Calor (aumento de temperatura local — ↑fluxo sanguíneo), (3) Tumor (edema — ↑permeabilidade vascular), (4) Dor (estimulação de nociceptores — prostaglandinas, bradicinina), (5) Perda de função (functio laesa — consequence dos demais sinais). Esses sinais resultam da resposta vascular e celular à lesão.`},{id:`fisio-082`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`hematologia`,subtopico:`Eritropoiese`,dificuldade:`medio`,enunciado:`A eritropoiese é o processo de produção de eritrócitos. Sobre a eritropoiese, assinale a alternativa CORRETA:`,alternativas:[`A eritropoiese ocorre no baço de animais adultos, sendo a medula óssea irrelevante para a produção de eritrócitos.`,`A eritropoiese é estimulada pela eritropoietina (EPO), produzida principalmente pelos rins em resposta à hipóxia, que estimula a diferenciação e proliferação de precursores eritróides na medula óssea.`,`A eritropoietina é produzida pelo fígado em resposta à hiperglicemia.`,`Os eritrócitos maduros de mamíferos possuem núcleo e mitocôndrias, permitindo a fosforilação oxidativa.`,`A eritropoiese é inibida pela hipóxia e estimulada pela hiperoxia.`],resposta_correta:`B`,explicacao:`A eritropoietina (EPO) é uma glicoproteína produzida (~90%) pelas células intersticiais peritubulares do RIM em resposta à hipóxia (detectada por HIF — fator induzido por hipóxia). A EPO estimula a diferenciação de progenitores eritróides (CFU-E → proeritroblasto → eritrócito maduro). Eritrócitos de mamíferos (opção D) são ANUCLEADOS e sem mitocôndrias (reticulócitos perdem organelas na maturação). O fígado (opção C) produz EPO fetal.`},{id:`fisio-083`,banca:`CESPE`,ano:2019,prova:`CESPE — Analista MAPA 2019`,tipo:`concurso`,topico:`hematologia`,subtopico:`Leucopoiese`,dificuldade:`medio`,enunciado:`Sobre a leucopoiese e os tipos de leucócitos, assinale a alternativa CORRETA:`,alternativas:[`Os neutrófilos são os leucócitos mais abundantes no sangue de cães (~60-70%) e são as primeiras células a chegar ao local de infecção bacteriana (fagocitose).`,`Os linfócitos são os leucócitos mais abundantes no sangue de cães, representando ~70% do total de leucócitos.`,`Os eosinófilos aumentam em infecções bacterianas agudas e diminuem em parasitoses e alergias.`,`Os basófilos são os leucócitos mais abundantes no sangue periférico de mamíferos.`,`Os monócitos circulam no sangue e não se diferenciam em macrófagos nos tecidos.`],resposta_correta:`A`,explicacao:`Em cães, os neutrófilos segmentados são os leucócitos mais abundantes (~60-70% da contagem diferencial). São as primeiras células a migrar para o local de infecção (quimiotaxia), onde fagocitam e eliminam bactérias. Linfócitos (opção B) são ~20-30% em cães (em gatos, sim, linfócitos predominam). Eosinófilos (opção C) aumentam em parasitoses e alergias. Monócitos (opção E) diferenciam-se em macrófagos nos tecidos.`},{id:`fisio-084`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Residência em Clínica de Pequenos Animais 2023`,tipo:`residencia`,topico:`hematologia`,subtopico:`Tipos sanguíneos`,dificuldade:`facil`,enunciado:`Sobre os sistemas de tipagem sanguínea em animais domésticos, assinale a alternativa CORRETA:`,alternativas:[`Os cães possuem o sistema ABO idêntico ao humano, com os tipos A, B, AB e O.`,`Os cães possuem o sistema DEA (Dog Erythrocyte Antigen), sendo o DEA 1.1 o mais clinicamente importante para transfusões, pois cães DEA 1.1 negativos que recebem sangue DEA 1.1 positivo podem desenvolver reação transfusional na segunda exposição.`,`Os gatos possuem apenas um tipo sanguíneo, não havendo risco de reação transfusional.`,`Os equinos não possuem sistema de tipagem sanguínea, sendo qualquer sangue compatível.`,`Em cães, a primeira transfusão de sangue incompatível sempre causa reação hemolítica imediata.`],resposta_correta:`B`,explicacao:`O sistema DEA é o principal sistema de tipagem sanguínea canina, com DEA 1.1 sendo o mais importante clinicamente. Cães DEA 1.1 negativos podem receber sangue DEA 1.1 positivo na primeira vez sem reação aguda (não há anticorpos naturais anti-DEA 1.1), mas na segunda exposição desenvolvem anticorpos que causam reação hemolítica. Gatos (opção C) possuem tipos A, B e AB. Equinos (opção D) possuem sistema A, C, D, K, P, Q, U.`},{id:`fisio-085`,banca:`ENAV`,ano:2018,prova:`ENAV — Concurso 2018`,tipo:`enav`,topico:`hematologia`,subtopico:`Coagulação`,dificuldade:`dificil`,enunciado:`A cascata de coagulação envolve fatores plasmáticos que são ativados sequencialmente. Sobre a via intrínseca da coagulação, assinale a alternativa CORRETA:`,alternativas:[`A via intrínseca é ativada pelo fator tecidual (FT) e fator VII, e medeia a coagulação em segundos.`,`A via intrínseca é ativada pelo contato do sangue com superfícies estranhas (fator XII — Hageman), e é avaliada clinicamente pelo tempo de tromboplastina parcial ativada (TTPA).`,`A via intrínseca é avaliada pelo tempo de protrombina (TP) e é independente dos fatores VIII e IX.`,`A via intrínseca e a via extrínseca convergem no fator Xa, que é o ponto de junção das duas vias.`,`A vitamina K é necessária apenas para a via intrínseca, não participando da via extrínseca.`],resposta_correta:`B`,explicacao:`A via intrínseca é ativada pelo contato com superfícies estranhas (colágeno, vidro): fator XII → XIIa → XI → XIa → IX → IXa (com VIIIa como cofator) → X → Xa. Avaliada pelo TTPA. A via extrínseca (opção A) é ativada por FT + VII, avaliada pelo TP. Ambas convergem em Xa (opção D) — correto, mas B é mais abrangente. A vitamina K (opção E) é necessária para fatores II, VII, IX, X (ambas as vias) e proteínas C/S.`},{id:`fisio-086`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`metabolismo`,subtopico:`Glicólise`,dificuldade:`medio`,enunciado:`A glicólise é a via metabólica que degrada glicose em piruvato. Sobre a glicólise, assinale a alternativa CORRETA:`,alternativas:[`A glicólise ocorre na mitocôndria e produz 36 ATP por molécula de glicose.`,`A glicólise ocorre no citoplasma, produzindo 2 moléculas de piruvato, 2 ATP (ganho líquido) e 2 NADH por molécula de glicose.`,`A glicólise ocorre exclusivamente em condições aeróbias e não pode funcionar sem oxigênio.`,`A glicólise produz CO₂ como produto final, liberando carbono como gás carbônico.`,`A enzima hexoquinase é irreversível e regulada, mas não é o ponto de controle mais importante da glicólise.`],resposta_correta:`B`,explicacao:`A glicólise ocorre no CITOSOL (opção A — mitocôndria é Krebs/CET). Glicose (6C) → 2 piruvato (3C). Balanço: 2 ATP (líquido — investimento 4, gasto 2) e 2 NADH. Funciona em aerobiose E anaerobiose (opção C). Não produz CO₂ (opção D). As enzimas regulatórias principais: hexoquinase, PFK-1 (ponto mais importante — opção E) e piruvato quinase.`},{id:`fisio-087`,banca:`UFBA`,ano:2022,prova:`UFBA — Residência em Clínica de Ruminantes 2022`,tipo:`residencia`,topico:`metabolismo`,subtopico:`Ciclo de Krebs`,dificuldade:`medio`,enunciado:`O ciclo de Krebs (ciclo do ácido tricarboxílico/TCA) é a via central do metabolismo oxidativo. Sobre o ciclo de Krebs, assinale a alternativa CORRETA:`,alternativas:[`O ciclo de Krebs ocorre no citoplasma celular e não depende de oxigênio para funcionar.`,`O ciclo de Krebs ocorre na matriz mitocondrial e, para cada molécula de acetil-CoA que entra no ciclo, produz 3 NADH, 1 FADH₂, 1 GTP (equivalente a ATP) e libera 2 CO₂.`,`O ciclo de Krebs produz diretamente a maior parte do ATP celular, sem necessidade da cadeia de transporte de elétrons.`,`O ciclo de Krebs funciona apenas no metabolismo de carboidratos, não participando do metabolismo de lipídeos ou aminoácidos.`,`A enzima citrato sintase catalisa a reação mais rápida e irreversível do ciclo, sendo o principal ponto de regulação.`],resposta_correta:`B`,explicacao:`O ciclo de Krebs na matriz mitocondrial: acetil-CoA (2C) + oxalacetato (4C) → citrato (6C) → ... → oxalacetato (4C). Por acetil-CoA: 3 NADH, 1 FADH₂, 1 GTP, 2 CO₂. O NADH e FADH₂ alimentam a cadeia de transporte de elétrons (opção C) para produzir ATP (~30-32 ATP/glicose total). O ciclo participa de carboidratos, lipídeos E aminoácidos (opção D). A citrato sintase (opção E) é regulada, mas isocitrato desidrogenase é o ponto mais importante.`},{id:`fisio-088`,banca:`CESPE`,ano:2021,prova:`CESPE — Analista MAPA 2021`,tipo:`concurso`,topico:`metabolismo`,subtopico:`Beta-oxidação`,dificuldade:`dificil`,enunciado:`Julgue o item sobre beta-oxidação de ácidos graxos:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A beta-oxidação dos ácidos graxos ocorre na matriz mitocondrial e, para cada ciclo, remove 2 carbonos da cadeia acil-CoA, produzindo 1 acetil-CoA, 1 NADH e 1 FADH₂. Antes de entrar na mitocôndria, os ácidos graxos de cadeia longa são ativados a acil-CoA e transportados pelo sistema carnitina (CPT-I e CPT-II), sendo a CPT-I o ponto de regulação da beta-oxidação.`,explicacao:`A beta-oxidação mitocondrial: acil-CoA → β-oxidação → acetil-CoA + NADH + FADH₂ (por ciclo, 2C removidos). O sistema carnitina transporta acil-CoA de cadeia longa: CPT-I (carnitina palmitoiltransferase I — membrana externa) é inibida por malonil-CoA (reguladora). Acil-CoA → acilcarnitina (CPT-I) → translocase → acil-CoA (CPT-II na matriz). O acetil-CoA entra no ciclo de Krebs ou produz corpos cetônicos (fígado).`},{id:`fisio-089`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Veterinário Concurso 2020`,tipo:`concurso`,topico:`metabolismo`,subtopico:`Gliconeogênese`,dificuldade:`medio`,enunciado:`A gliconeogênese é a síntese de glicose a partir de precursores não-glicídicos. Sobre a gliconeogênese, assinale a alternativa CORRETA:`,alternativas:[`A gliconeogênese ocorre exclusivamente no músculo esquelético, que é o principal produtor de glicose sanguínea.`,`A gliconeogênese ocorre principalmente no fígado (e parcialmente no rim) e utiliza precursores como lactato, glicerol, alanina e propionato. As enzimas exclusivas da gliconeogênese contornam as três reações irreversíveis da glicólise.`,`A gliconeogênese e a glicólise ocorrem simultaneamente na mesma célula, sem regulação recíproca.`,`A gliconeogênese utiliza exclusivamente aminoácidos como precursores, não podendo usar lactato ou glicerol.`,`A insulina é o principal hormônio estimulador da gliconeogênese.`],resposta_correta:`B`,explicacao:`A gliconeogênese ocorre principalmente no FÍGADO (~90%) e rim (~10%). Precursores: lactato (ciclo de Cori), glicerol (lipólise), aminoácidos gliconeogênicos (alanina, glutamina), propionato (ruminantes). Enzimas exclusivas: piruvato carboxilase, PEPCK, frutose-1,6-bisfosfatase, glicose-6-fosfatase (contornam reações irreversíveis da glicólise). A glicólise e gliconeogênese (opção C) são reguladas RECIPROCAMENTE. Insulina (opção E) INIBE gliconeogênese.`},{id:`fisio-090`,banca:`ENAV`,ano:2019,prova:`ENAV — Concurso 2019`,tipo:`enav`,topico:`metabolismo`,subtopico:`Metabolismo de lipídeos`,dificuldade:`medio`,enunciado:`O metabolismo dos lipídeos envolve diversas vias. Sobre o metabolismo lipídico, assinale a alternativa CORRETA:`,alternativas:[`A lipogênese ocorre no tecido adiposo e no fígado, a partir de acetil-CoA, e é estimulada pela insulina e inibida pelo glucagon.`,`A cetogênese ocorre no músculo esquelético durante o jejum prolongado, produzindo corpos cetônicos como combustível alternativo.`,`Os quilomícrons são produzidos pelo fígado e transportam lipídeos da dieta para os tecidos periféricos.`,`A lipase hormônio-sensível (HSL) do tecido adiposo é estimulada pela insulina e inibida pelas catecolaminas.`,`O colesterol é produzido exclusivamente pela dieta, não havendo síntese endógena.`],resposta_correta:`A`,explicacao:`A lipogênese (síntese de ácidos graxos) ocorre no citoplasma de hepatócitos e adipócitos, a partir de acetil-CoA (convertido a malonil-CoA pela acetil-CoA carboxilase — ACC). Insulina estimula lipogênese (ativa ACC, lipase de lipídios). Glucagon e catecolaminas inibem. A cetogênese (opção B) ocorre no FÍGADO (não músculo). Quilomícrons (opção C) são produzidos pelos enterócitos. HSL (opção D) é estimulada por catecolaminas e inibida por insulina.`},{id:`fisio-091`,banca:`UFPE`,ano:2021,prova:`UFPE — Residência em Clínica de Pequenos Animais 2021`,tipo:`residencia`,topico:`metabolismo`,subtopico:`Metabolismo de proteínas`,dificuldade:`medio`,enunciado:`O metabolismo de aminoácidos e proteínas é essencial para a homeostase. Sobre o metabolismo proteico, assinale a alternativa CORRETA:`,alternativas:[`Os aminoácidos em excesso são armazenados como proteínas indefinidamente, sem degradação.`,`Os aminoácidos em excesso sofrem desaminação (remoção do grupo amino), e o grupo amino é convertido em ureia no ciclo da ureia (fígado) para excreção renal, enquanto o esqueleto carbônico é oxidado no ciclo de Krebs ou usado para gliconeogênese/lipogênese.`,`A ureia é produzida nos rins a partir de amônia, sem envolvimento hepático.`,`Todos os aminoácidos são essenciais, devendo ser obtidos exclusivamente pela dieta.`,`O balanço nitrogenado positivo (ingestão > excreção) ocorre normalmente em adultos saudáveis em manutenção.`],resposta_correta:`B`,explicacao:`Aminoácidos em excesso sofrem desaminação (transaminação ou desaminação oxidativa). O grupo amino → NH₃ → ureia (ciclo da ureia no fígado — ornitina + NH₃ + CO₂ → citrulina → arginossuccinato → arginina → ureia + ornitina). O esqueleto carbônico (cetoácido) entra no Krebs ou é usado para gliconeogênese. Apenas 10 aminoácidos são essenciais (opção D). Balanço nitrogenado positivo (opção E) ocorre em crescimento, gestação e lactação.`},{id:`fisio-092`,banca:`ENAV`,ano:2022,prova:`ENAV — Concurso 2022`,tipo:`enav`,topico:`lactação`,subtopico:`Colostro`,dificuldade:`facil`,enunciado:`O colostro é o primeiro leite produzido após o parto e possui características imunológicas e nutricionais únicas. Sobre o colostro, assinale a alternativa CORRETA:`,alternativas:[`O colostro é idêntico ao leite maduro em composição, não havendo diferença entre as duas secreções.`,`O colostro é rico em imunoglobulinas (principalmente IgG em bovinos), proteínas, vitaminas lipossolúveis e possui maior valor energético que o leite maduro, sendo essencial para a transferência de imunidade passiva ao neonato.`,`O colostro contém exclusivamente IgA, sem presença de IgG ou IgM.`,`A absorção de imunoglobulinas do colostro pelo intestino do neonato é possível indefinidamente após o nascimento.`,`O colostro é produzido apenas por vacas e não por outras espécies domésticas.`],resposta_correta:`B`,explicacao:`O colostro é a primeira secreção mamária (24-72h pós-parto). Rico em: (1) IgG (em bovinos, ~85% das Igs — macromoléculas absorvidas por pinocitose intestinal), IgA (predomina em cães/gatos); (2) proteínas (albumina, lactoferrina); (3) vitaminas A, D, E; (4) minerais (Zn, Fe). A janela de absorção intestinal de Igs é limitada (fechamento intestinal — 24-48h em bovinos, variável entre espécies). A "leite de transição" sucede o colostro antes do leite maduro.`},{id:`fisio-093`,banca:`UFMT`,ano:2022,prova:`UFMT — Residência em Reprodução de Bovinos 2022`,tipo:`residencia`,topico:`lactação`,subtopico:`Glândula mamária`,dificuldade:`medio`,enunciado:`A glândula mamária é o órgão responsável pela síntese e secreção do leite. Sobre a morfologia e fisiologia da glândula mamária, assinale a alternativa CORRETA:`,alternativas:[`A glândula mamária é composta exclusivamente por tecido conjuntivo, sem componente epitelial secretor.`,`A unidade secretora da glândula mamária é o alvéolo, revestido por células epiteliais (lactócitos) e circundado por células mioepiteliais que contraem sob ação da ocitocina para a ejeção do leite.`,`A glândula mamária bovina possui quatro pares de tetos, totalizando oito tetas.`,`O leite é produzido nos ductos lactíferos e armazenado nos alvéolos até a ordenha.`,`A síntese de lactose ocorre no retículo endoplasmático rugoso das células mioepiteliais.`],resposta_correta:`B`,explicacao:`A unidade secretora é o ALVÉOLO mamário, revestido por lactócitos (células epiteliais cuboidais) que sintetizam componentes do leite (proteínas, gordura, lactose). As células mioepiteliais circundantes contraem sob ação da ocitocina (reflexo de ejeção). Bovinos possuem 4 glândulas mamárias (4 tetas — opção C). A lactose (opção E) é sintetizada no complexo de Golgi (α-lactalbumina + galactosil transferase).`},{id:`fisio-094`,banca:`VUNESP`,ano:2018,prova:`VUNESP — Veterinário Concurso 2018`,tipo:`concurso`,topico:`lactação`,subtopico:`Lactose`,dificuldade:`facil`,enunciado:`A lactose é o principal carboidrato do leite de mamíferos. Sobre a lactose, assinale a alternativa CORRETA:`,alternativas:[`A lactose é um dissacarídeo formado por glicose e frutose, sintetizado no complexo de Golgi das células epiteliais mamárias.`,`A lactose é um dissacarídeo formado por glicose e galactose, sintetizado pela enzima lactose sintase (galactosil transferase + α-lactalbumina) no complexo de Golgi dos lactócitos.`,`A lactose é produzida exclusivamente a partir de aminoácidos, sem envolvimento de carboidratos.`,`A lactose é a principal fonte de energia do leite, mas não contribui para a pressão osmótica do leite.`,`A lactase é uma enzima produzida na glândula mamária que quebra a lactose durante a síntese do leite.`],resposta_correta:`B`,explicacao:`A lactose (galactose + glicose) é o principal carboidrato do leite (~4,5% no leite bovino). Sintetizada no complexo de Golgi pela lactose sintase: galactosil transferase (enzima) + α-lactalbumina (reguladora — produzida sob ação da prolactina). A lactose é o principal determinante da pressão osmótica do leite (opção D — está ERRADO). A lactase (opção E) é produzida nos enterócitos (borda em escova) e quebra lactose em glicose + galactose para absorção intestinal.`},{id:`fisio-095`,banca:`ENAV`,ano:2021,prova:`ENAV — Concurso 2021`,tipo:`enav`,topico:`exercício`,subtopico:`Adaptações ao exercício`,dificuldade:`medio`,enunciado:`Durante o exercício físico, diversos sistemas sofrem adaptações agudas. Sobre as respostas cardiovasculares ao exercício, assinale a alternativa CORRETA:`,alternativas:[`Durante o exercício, a frequência cardíaca diminui para preservar energia, enquanto o volume sistólico aumenta.`,`Durante o exercício, o débito cardíaco aumenta devido ao aumento da frequência cardíaca e do volume sistólico, com redistribuição do fluxo sanguíneo para os músculos ativos (vasodilatação muscular) em detrimento de órgãos esplâncnicos.`,`A pressão arterial sistólica diminui durante o exercício devido à vasodilatação periférica generalizada.`,`Durante o exercício, o fluxo sanguíneo para o trato gastrointestinal aumenta para suportar a digestão.`,`A resposta cardiovascular ao exercício é exclusivamente mediada pelo sistema parassimpático.`],resposta_correta:`B`,explicacao:`No exercício: ↑FC (simpático, ↓parassimpático) + ↑VS (Frank-Starling, ↑contratilidade) = ↑DC (até 4-5x). Redistribuição: ↑fluxo muscular (vasodilatação metabólica — adenosina, K⁺, H⁺, CO₂), ↓fluxo esplâncnico (vasoconstritor simpático), ↑fluxo coronariano. PA sistólica (opção C) aumenta (↑DC). O simpático (opção E) media a taquicardia, mas a vasodilatação muscular é miogênica/metabólica.`},{id:`fisio-096`,banca:`UFMT`,ano:2020,prova:`UFMT — Residência em Equinos 2020`,tipo:`residencia`,topico:`exercício`,subtopico:`VO2 e limiar anaeróbio`,dificuldade:`dificil`,enunciado:`O consumo máximo de oxigênio (VO₂máx) e o limiar anaeróbio são indicadores da capacidade aeróbia. Sobre esses conceitos, assinale a alternativa CORRETA:`,alternativas:[`O VO₂máx é a quantidade máxima de oxigênio que pode ser consumida por unidade de tempo durante exercício submáximo, e não pode ser alterada pelo treinamento.`,`O VO₂máx é o limite máximo da capacidade aeróbia, determinado pelo débito cardíaco máximo, conteúdo arterial de O₂ e extração periférica de O₂. O treinamento aeróbio aumenta o VO₂máx em 15-20%.`,`O limiar anaeróbio ocorre quando o consumo de O₂ excede a demanda metabólica, resultando em excesso de oxigênio no sangue.`,`O limiar anaeróbio é o ponto em que a produção de lactato excede a capacidade de remoção, causando acúmulo progressivo de lactato no sangue, e ocorre tipicamente entre 50-60% do VO₂máx em animais treinados.`,`Cavalos de corrida possuem VO₂máx inferior ao de cães, sendo menos adaptados ao exercício intenso.`],resposta_correta:`B`,explicacao:`O VO₂máx = DCmax × (CaO₂ - CvO₂) = débito cardíaco máximo × diferença arteriovenosa de O₂. É o melhor indicador de capacidade aeróbia. O treinamento aeróbio aumenta o VO₂máx (↑DCmax, ↑extração O₂). O limiar anaeróbio (opção D) ocorre em ~60-80% do VO₂máx em animais treinados (não 50-60%). Cavalos (opção E) têm VO₂máx ~180-220 mL/kg/min, entre os mais altos dos mamíferos.`},{id:`fisio-097`,banca:`CRMV`,ano:2019,prova:`CRMV — Exame de Qualificação 2019`,tipo:`crmv`,topico:`exercício`,subtopico:`Termorregulação no exercício`,dificuldade:`medio`,enunciado:`A produção de calor durante o exercício desafia o sistema termorregulador. Sobre a termorregulação durante o exercício em cães, assinale a alternativa CORRETA:`,alternativas:[`Cães dissipam calor durante o exercício exclusivamente por condução e convecção, sem participação da evaporação.`,`Cães dependem principalmente do ofegar (panting) para dissipar calor durante o exercício, por evaporação nas vias respiratórias, pois possuem poucas glândulas sudoríparas funcionais.`,`O ofegar em cães não consome energia significativa e não interfere no desempenho atlético.`,`Cães podem aumentar a frequência respiratória de 30 para 300 movimentos/min durante o ofegar, mantendo a ventilação alveolar constante.`,`A hipertermia em cães é clinicamente significativa apenas acima de 45°C, sendo 42°C uma temperatura segura durante o exercício.`],resposta_correta:`B`,explicacao:`Cães dissipam calor principalmente pelo ofegar (panting): evaporação da água nas vias respiratórias e língua. Possuem glândulas sudoríparas apenas nas almofadas digitais (insuficientes para termorregulação). O ofegar (opção C) consome energia (músculos respiratórios), mas é o mecanismo mais eficiente. A FC respiratória pode ultrapassar 300/min (opção D), mas o padrão muda (superficial → efetivo). Temperatura >41°C (opção E) já é hipertermia de esforço; >43°C é potencialmente fatal.`},{id:`fisio-098`,banca:`ENAV`,ano:2016,prova:`ENAV — Concurso 2016`,tipo:`enav`,topico:`termorregulação`,subtopico:`Febre`,dificuldade:`medio`,enunciado:`A febre é uma resposta regulada à elevação do ponto de ajuste (set point) da temperatura corporal. Sobre a febre, assinale a alternativa CORRETA:`,alternativas:[`A febre é causada por hipertermia desregulada, sem envolvimento de mediadores químicos.`,`A febre ocorre quando pirógenos (exógenos como LPS bacteriano, endógenos como IL-1, IL-6, TNF-α) atuam no hipotálamo, elevando o set point da temperatura. O organismo então ativa mecanismos de produção de calor (vasoconstrição, tremor) para atingir o novo set point.`,`Durante a febre, o paciente apresenta vasodilatação cutânea e sudorese desde o início do quadro.`,`Os antipiréticos (dipirona, paracetamol) atuam bloqueando a produção de IL-1 e TNF-α pelos macrófagos.`,`A febre é sempre prejudicial ao organismo e deve ser tratada imediatamente em todos os casos.`],resposta_correta:`B`,explicacao:`Na febre: pirógenos exógenos (LPS) → ativação macrófagos → pirógenos endógenos (IL-1, IL-6, TNF-α, IFN) → hipotálamo (núcleo pré-óptico) → ↑PGE2 → ↑set point. O corpo "acha" que está frio → vasoconstrição (pele fria), tremor (calafrios), comportamento de busca por calor. Quando o set point cai (ação do antipirético): vasodilatação + sudorese (crise febril). Antipiréticos (opção D) inibem COX-2/PGE2 hipotalâmica.`},{id:`fisio-099`,banca:`CESPE`,ano:2017,prova:`CESPE — Analista MAPA 2017`,tipo:`concurso`,topico:`termorregulação`,subtopico:`Hipotermia`,dificuldade:`facil`,enunciado:`Julgue o item sobre hipotermia:`,alternativas:[`VERDADEIRO`,`FALSO`],resposta_correta:`A`,vf:!0,vf_texto:`A hipotermia é definida como temperatura corporal abaixo de 36°C e pode ser classificada em leve (32-36°C), moderada (28-32°C) e grave (<28°C). Em animais domésticos, a hipotermia grave compromete a função cardíaca (bradicardia, arritmias), a respiração e o nível de consciência, sendo uma emergência clínica que requer reaquecimento ativo.`,explicacao:`A hipotermia (T < 36°C) é classificada em: Leve (32-36°C — tremores, taquicardia), Moderada (28-32°C — ↓tremores, bradicardia, sonolência), Grave (<28°C — bradicardia grave, arritmias, perda de consciência, risco de fibrilação ventricular). Em animais, a hipotermia é comum em anestesia, neonatos e exposição ao frio. Reaquecimento: ativo externo (cobertores, ar quente) e interno (fluidos aquecidos, oxigênio aquecido).`},{id:`fisio-100`,banca:`UNESP`,ano:2020,prova:`UNESP — Residência em Clínica de Pequenos Animais 2020`,tipo:`residencia`,topico:`termorregulação`,subtopico:`Mecanismos de dissipação de calor`,dificuldade:`medio`,enunciado:`Os mecanismos de dissipação de calor em animais domésticos envolvem processos físicos e fisiológicos. Sobre os mecanismos de dissipação, assinale a alternativa CORRETA:`,alternativas:[`A condução é o principal mecanismo de dissipação de calor em cães, representando mais de 80% da perda de calor.`,`A evaporação (ofegar) é o principal mecanismo de dissipação de calor em cães e gatos, sendo responsável por até 60-70% da perda de calor em ambientes quentes, pois a evaporação de água consome calor latente.`,`A radiação térmica não contribui para a perda de calor em animais domésticos.`,`A vasoconstrição cutânea é o principal mecanismo de dissipação de calor em ambientes quentes.`,`Os animais domésticos podem aumentar a sudorese por todo o corpo como resposta ao calor, semelhante aos humanos.`],resposta_correta:`B`,explicacao:`Em cães/gatos em ambiente quente, a evaporação é o mecanismo mais eficiente (até 60-70% da perda de calor): ofegar evapora água das vias respiratórias e língua, consumindo calor latente de vaporização (~580 kcal/L). A radiação (opção C) contribui em ambiente neutro (~30%). Condução (opção A) é importante quando o animal está em contato com superfícies frias. Vasodilatação cutânea (não vasoconstrição — opção D) aumenta a perda por radiação/convecção.`},{id:`fisio-101`,banca:`FCC`,ano:2019,prova:`FCC — Veterinário IBAMA 2019`,tipo:`concurso`,topico:`metabolismo`,subtopico:`Glicólise`,dificuldade:`facil`,enunciado:`A glicólise é a primeira etapa da degradação da glicose. Sobre a glicólise em condições anaeróbias, assinale a alternativa CORRETA:`,alternativas:[`Em condições anaeróbias, o piruvato produzido pela glicólise é convertido em lactato pela lactato desidrogenase (LDH), regenerando NAD⁺ para que a glicólise continue.`,`Em condições anaeróbias, o piruvato é convertido em acetil-CoA para entrada no ciclo de Krebs.`,`A glicólise anaeróbia produz 36 ATP por molécula de glicose, semelhante à via aeróbia.`,`Em condições anaeróbias, a glicólise é completamente inibida e a célula não produz ATP.`,`A conversão de piruvato em lactato consome NADH, reduzindo o pool de equivalentes de redução.`],resposta_correta:`A`,explicacao:`Em anaerobiose: piruvato + NADH → lactato + NAD⁺ (LDH). A regeneração de NAD⁺ é essencial para a continuidade da glicólise (a glicólise precisa de NAD⁺ na reação da gliceraldeído-3-fosfato desidrogenase). Sem NAD⁺, a glicólise para e a célula não produz ATP. O lactato produzido é transportado ao fígado (ciclo de Cori) ou oxidado no músculo quando O₂ retorna. A glicólise anaeróbia (opção C) produz apenas 2 ATP.`},{id:`fisio-102`,banca:`AVAMEC`,ano:2021,prova:`AVAMEC — Prova de Título em Clínica de Grandes Animais 2021`,tipo:`concurso`,topico:`nervoso`,subtopico:`Medula espinhal`,dificuldade:`dificil`,enunciado:`Sobre os reflexos espinhais e sua localização em cães, é CORRETO afirmar:`,alternativas:[`O reflexo patelar (miotático quadríceps) é medido na localização L4-L6 e é mediado pelo nervo femoral.`,`O reflexo gastrocnêmio é medido na localização L7-S1 e é mediado pelo nervo tibial.`,`O reflexo do tríceps é medido na localização C6-T1 e é mediado pelo nervo radial.`,`O reflexo de retirada (flexor) é um reflexo polissináptico mediado pelas raízes L4-S1 que protege o membro de estímulos nocivos.`,`Todas as alternativas anteriores estão corretas.`],resposta_correta:`E`,explicacao:`Todas as afirmações estão corretas: (A) Reflexo patelar — L4-L6, nervo femoral (quadríceps). (B) Reflexo gastrocnêmio — L7-S1, nervo tibial (gastrocnêmio). (C) Reflexo do tríceps — C6-T1, nervo radial (tríceps). (D) Reflexo de retirada — polissináptico (L4-S1) — flexor, protege o membro. A localização dos reflexos é essencial para o diagnóstico neurológico topográfico em cães.`},{id:`fisio-103`,banca:`ENAV`,ano:2016,prova:`ENAV — Concurso 2016`,tipo:`enav`,topico:`respiratorio`,subtopico:`Volumes pulmonares`,dificuldade:`medio`,enunciado:`O volume residual (VR) é um componente importante da mecânica pulmonar. Sobre o volume residual, assinale a alternativa CORRETA:`,alternativas:[`O volume residual é o volume de ar que permanece nos pulmões após uma expiração máxima e não pode ser expirado voluntariamente.`,`O volume residual pode ser completamente expirado por esforço voluntário máximo.`,`O volume residual é de aproximadamente 1 mL/kg, sendo insignificante para as trocas gasosas.`,`O volume residual existe apenas em cães braquicefálicos, não sendo encontrado em cães dolicocefálicos.`,`O volume residual não é influenciado pela idade do animal, permanecendo constante ao longo da vida.`],resposta_correta:`A`,explicacao:`O volume residual (VR) é o ar que permanece nos pulmões após expiração máxima forçada (~10-15 mL/kg em cães). Não pode ser expirado voluntariamente. É importante para manter a oxigenação alveolar contínua entre as respirações e evitar colapso alveolar. Com a idade (opção E), o VR aumenta (perda de elasticidade pulmonar — enfisema senil). A capacidade pulmonar total (CPT) = CV + VR.`},{id:`fisio-104`,banca:`CESPE`,ano:2023,prova:`CESPE — Analista MAPA 2023`,tipo:`concurso`,topico:`endocrino`,subtopico:`Tireoide`,dificuldade:`medio`,enunciado:`A tireoide produz hormônios essenciais para o metabolismo. Sobre a síntese dos hormônios tireoidianos, assinale a alternativa CORRETA:`,alternativas:[`Os hormônios tireoidianos (T3 e T4) são peptídeos hidrossolúveis que se ligam a receptores de membrana celulares.`,`A síntese de T3 e T4 requer iodação da tireoglobulina no coloide folicular, mediada pela tireoperoxidase (TPO). O T4 é a principal forma secretada, mas o T3 é a forma biologicamente ativa (3-5x mais potente).`,`O T4 é a forma ativa e o T3 é a forma inativa do hormônio tireoidiano.`,`A tireoide produz apenas T4, sendo que o T3 é produzido exclusivamente pelo hipotálamo.`,`A tireoperoxidase (TPO) não é necessária para a síntese dos hormônios tireoidianos.`],resposta_correta:`B`,explicacao:`A síntese tireoidiana: (1) captação de I⁻ pelo NIS (simportador Na⁺/I⁻), (2) oxidação do I⁻ pela TPO, (3) iodação da tireoglobulina (MIT → DIT), (4) acoplamento (MIT+DIT→T3, DIT+DIT→T4), (5) armazenamento no colóide, (6) proteólise e liberação. T4 é secretada em maior quantidade, mas T3 é 3-5x mais potente. Conversão T4→T3 por desiodases periféricas. T3/T4 são lipossolúveis (opção A) e ligam-se a receptores nucleares.`},{id:`fisio-105`,banca:`ENAV`,ano:2018,prova:`ENAV — Concurso 2018`,tipo:`enav`,topico:`reprodutivo`,subtopico:`Ovulação`,dificuldade:`medio`,enunciado:`A ovulação é o processo de liberação do oócito do folículo ovariano. Sobre a ovulação em diferentes espécies, assinale a alternativa CORRETA:`,alternativas:[`Todas as espécies domésticas são ovuladoras espontâneas, sem necessidade de cópula para induzir a ovulação.`,`As gatas são ovuladoras induzidas (reflexas), sendo que a ovulação é desencadeada pelo estímulo mecânico da cópula.`,`As cadelas ovulham ovócitos maduros (secundários), prontos para fertilização imediata.`,`As vacas ovulam dois oócitos por ciclo estral para aumentar a chance de gestação.`,`A ovulação em todas as espécies ocorre 24 horas antes do início do estro.`],resposta_correta:`B`,explicacao:`Gatas são ovuladoras INDUZIDAS: a cópula (estímulo mecânico na vagina/cérvix) desencadeia o pico de LH → ovulação. Sem cópula, não há ovulação e o folículo luteiniza parcialmente (cisto folicular). Cães, vacas, éguas (opção A) são ovuladoras espontâneas. Cadelas (opção C) ovulam ovócitos IMATUROS (primário). Vacas (opção D) ovulam 1 ovócito. A ovulação (opção E) ocorre APÓS o início do estro.`}],i={totalQuestoes:r.length,porBanca:Object.entries(r.reduce((e,t)=>(e[t.banca]=(e[t.banca]||0)+1,e),{})).map(([t,n])=>({banca:t,total:n,...e[t]})),porAno:Object.entries(r.reduce((e,t)=>(e[t.ano]=(e[t.ano]||0)+1,e),{})).map(([e,t])=>({ano:Number(e),total:t})).sort((e,t)=>t.ano-e.ano),porTopico:Object.entries(r.reduce((e,t)=>(e[t.topico]=(e[t.topico]||0)+1,e),{})).map(([e,t])=>({topico:e,nome:n[e]?.nome,total:t})),porDificuldade:Object.entries(r.reduce((e,t)=>(e[t.dificuldade]=(e[t.dificuldade]||0)+1,e),{})).map(([e,t])=>({dificuldade:e,total:t}))};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_FISIOLOGIA,t as TIPOS_PROVA,n as TOPICOS_FISIOLOGIA};